    "\n"
    "ddlLock::dropWrite\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  // set grid as started\n"
    "  true grid.started!\n"
    "  grid.thisNodeName@ \\\"Node %v : SE cluster started\\\" str.format .\n"
    "\n"
    "  //1000000 thread.sleep_s\n"
    "\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT connectorActor.sen"_Str
  ;

