    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_grid allot\n"
    "  word.this >body object.magic!\n"
    "  CN_GRID word.this >body object.class!\n"
    "  word.this >body grid.init\n"
    "  ' grid word.this word.kind!\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "grid: grid.this\n"
    "\n"
    "grid.appendNodes\n"
    "grid.thisNode!\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT grid.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of gridModel.sen
  sDefinition =
    "\""
    "\\\"munged gridModel.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* gridModel.sen -- grid model group                                          */\n"
    "/*============================================================================*/\n"
    "\n"
    "int:  queryCount\n"
    "\n"
    "\\\"gridModel.sen\\\" .verbose\n"
    "\n"
    "\\\"node.sen\\\" include\n"
    "\\\"grid.sen\\\" include\n"
    "\\\"nodeCursor.sen\\\" include\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT gridModel.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of index.sen
  sDefinition =
    "\""
    "\\\"munged index.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* index.sen -- index related words                                           */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"index.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* index is used as a kind of word to identify indexes                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an indexes folder under given named table                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndexes ( \\\"<tableNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING INDEXES FOR TABLE \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"indexes\\\"     ( dic \\\"indexes\\\" )\n"
    "  swap         ( \\\"indexes\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    ": isIndex word.kind@ ' index eql ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name from input stream (doesnt leave index on stk)   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_index allot\n"
    "  word.this >body object.magic!\n"
    "  CN_INDEX word.this >body object.class!\n"
    "  word.this >body index.init\n"
    "  true word.this >body object.wordbody!\n"
    "  ' index word.this word.kind!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index using name on the stack (leaves index on stack)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :index\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_index allot\n"
    "  word.this >body object.magic!\n"
    "  CN_INDEX word.this >body object.class!\n"
    "  word.this >body index.init\n"
    "  true word.this >body object.wordbody!\n"
    "  ' index word.this word.kind!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within indexes folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinIndexes\n"
    "  0 pathPick dic.name \\\"indexes\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInIndexes\n"
    "  withinIndexes if true exit then\n"
    "  EC_NOT_IN_INDEXES false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* assert top of task dictionary stack is indexes                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": assertInIndexes ( -- t|f )\n"
    "  withinIndexes assert\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check word is an index                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsIndex ( \\\"<indexNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  0 locals| indexPtr indexNm |\n"
    "\n"
    "  indexNm find ( indexPtr )\n"
    "  to indexPtr\n"
    "\n"
    "  indexPtr\n"
    "  not ( indexPtr bool )\n"
    "\n"
    "  if\n"
    "    EC_NO_SUCH_INDEX false ( errorCode false )\n"
    "  exit\n"
    "  then\n"
    "\n"
    "  indexPtr ( indexPtr )\n"
    "  word.kind@ ( ^word )\n"
    "  ' index ( ^word ^word )\n"
    "  eql ( bool )\n"
    "  if\n"
    "    //indexPtr execute index.isHidden@ if\n"
    "    //  EC_NO_SUCH_INDEX false ( errorCode false )\n"
    "    //  exit\n"
    "    //then\n"
    "\n"
    "    true ( true )\n"
    "    exit\n"
    "  then\n"
    "\n"
    "\n"
    "  EC_NOT_AN_INDEX false ( errorCode false )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes folder                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkIsNotIndex ( \\\"<word>\\\" )\n"
    "\n"
    "  findInCurrent not if true exit then\n"
    "  EC_INDEX_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the index sub folder and push it onto task dictionary                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexSub ( \\\"<indexNm>\\\" -- )\n"
    "  dup checkIsIndex not if EC_NO_SUCH_INDEX false exit then\n"
    "  find execute index.subDic pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the index sub folder                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexSub\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the indexes folder and push it onto task dictionary                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexes ( -- )\n"
    "  \\\"indexes\\\" find execute pathPush\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the indexes folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexes\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable index                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeIndex ( \\\"<indexNm>\\\" \\\"<tableNm>\\\" --  true | errorCode false )\n"
    "\n"
    "  locals| tableNm indexNm |\n"
    "\n"
    "  checkInTables not if false exit then\n"
    "\n"
    "  tableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  tableNm pushTable assert\n"
    "  pushIndexes assert\n"
    "\n"
    "  indexNm checkIsNotIndex not if popIndexes popTable assertInTables false exit then\n"
    "\n"
    "  popIndexes\n"
    "  popTable\n"
    "\n"
    "  assertInTables\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable index folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveIndex ( \\\"<indexNm>\\\" \\\"<tableNm>\\\" -- true | errorCode false )\n"
    "\n"
    "  locals| tableNm indexNm |\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables       not if false exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  tableNm checkIsTableFolder not if false exit then\n"
    "\n"
    "  true ( \\\"<indexNm>\\\" true )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* tidy up of the index                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": indexTidyUp ( \\\"<indexNm>\\\" -- )\n"
    "\n"
    "\\\"indextdyup\\\" .\n"
    "dup .\n"
    "   find execute ( ^indexPtr )\n"
    "\n"
    "   // truncate the index\n"
    "   dup index.truncate\n"
    "   \n"
    "   // forget all column names\n"
    "   dup index.subDic\n"
    "   pathPush\n"
    "   \\\"columns\\\" find execute forgetAll\n"
    "   pathDrop\n"
    "\n"
    "  // forget the sub dictionary\n"
    "   index.subDic forgetAll\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyze an index of a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIndex allParticipants 2 returnResult ( detailed \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: analyzeIndex\n"
    "\n"
    "  find execute\n"
    "  index.analyze\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get index pointer and put into task.seitf.currentIndex                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": getIndex ( \\\"<indexNm>\\\" -- <R> )\n"
    "\n"
    "  checkInIndexes not if drop false exit then\n"
    "\n"
    "  // get index ptr\n"
    "  findInCurrent execute\n"
    "\n"
    "  task::this task.seitf@ seitf.indexGet\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* clear task.seitf.currentIndex                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": returnIndex ( )\n"
    "\n"
    "  task::this task.seitf@ seitf.indexReturn\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make_index (invoked from makeIndex)                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": make_index ( \\\"<tableNm>\\\" \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  0 0 locals| indexPtr tablePtr indexNm tableNm |\n"
    "\n"
    "  pushIndexes\n"
    "\n"
    "  // create the index\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "  :index ( ^index )\n"
    "\n"
    "  // drop the index word\n"
    "  drop (  )\n"
    "\n"
    "  // make index columns\n"
    "  indexNm \\\"makeIndexColumns\\\" find execute\n"
    "\n"
    "  indexNm ( \\\"<indexNm>\\\" )\n"
    "\n"
    "  // find the index\n"
    "  find execute ( ^index )\n"
    "  to indexPtr\n"
    "\n"
    "  // find the table\n"
    "  tableNm find execute\n"
    "  to tablePtr\n"
    "\n"
    "  // push the table and index\n"
    "  tablePtr indexPtr ( ^index ^table )\n"
    "\n"
    "  // set the table in the index\n"
    "  index.table! (  )\n"
    "\n"
    "  // add the index in the table\n"
    "  indexPtr tablePtr table.addIndex\n"
    "\n"
    "  popIndexes\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index (run by participant)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndex allParticipants 2 checkResult ( \\\"<tableNm>\\\" \\\"<indexNm>\\\"  -- true n# true )\n"
    "\n"
    "tp: makingIndex\n"
    "\n"
    "  locals| indexNm tableNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "  \\\"MAKING INDEX \\\" indexNm str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tableNm ( \\\"<tableNm>\\\" )\n"
    "  find execute pathPush\n"
    "\n"
    "  tableNm indexNm make_index\n"
    "\n"
    "  popTable\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by keySelectIndex request)    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": keySelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" ^indexPtr seitf -- )\n"
    "\n"
    "  0 0 0 locals| entry tempEntryBuffer indexBuffer seitf indexPtr upper lower key |\n"
    "\n"
    "  tp: keySelectIdx\n"
    "\n"
    "  seitf task::this task.seitf!\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    " //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // get the indexBuffer looking for the key\n"
    "  key indexPtr index.buffer ( indexBuffer )\n"
    "  to indexBuffer\n"
    "\n"
    "  // position in the index buffer at the key\n"
    "  key indexBuffer indexPtr index.position\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no key match\n"
    "  begin\n"
    "    entry\n"
    "    while\n"
    "\n"
    "    // check if exact key match\n"
    "    key indexPtr entry entry.matches if\n"
    "\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        //\\\"Creating a tempIndexBuffer\\\" .\n"
    "        indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry did not match the key, null the entry and break from loop\n"
    "      0  to entry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make an index (run by participant)                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadIndexes allParticipants 0 checkResult ( -- true n# true )\n"
    "\n"
    "tp: loadIndexes\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"LOADING INDEXES on NODE \\\" grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  \\\"indexes\\\"\n"
    "  find execute pathPush\n"
    "\n"
    "  0 pathPick dic.lastWord dup\n"
    "    iterate\n"
    "    object@ word.name\n"
    "    find execute ( ^index )\n"
    "\n"
    "    // populate only non-hidden indexes\n"
    "    dup index.isHidden@ not if\n"
    "      index.populate\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!\n"
    "  next\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lowerSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" ^indexPtr seitf -- )\n"
    "\n"
    "  0 0 0 locals| entry tempEntryBuffer indexBuffer seitf indexPtr upper lower key |\n"
    "\n"
    "  tp: lowerSelectIdxTask\n"
    "\n"
    "  seitf task::this task.seitf!\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // get the indexBuffer looking for the lower key\n"
    "  lower indexPtr index.buffer ( indexBuffer )\n"
    "  to indexBuffer\n"
    "\n"
    "  // position in the index buffer at the lower key\n"
    "  lower indexBuffer indexPtr index.position\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "    \n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "    \n"
    "    // insert row from entry in tempEntryBuffer\n"
    "    //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "    indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "    // check if we managed to insert the entry\n"
    "    not if\n"
    "      // buffer must be full\n"
    "      // put this tempEntryBuffer in seitf bufferQueue\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "      // create another temporary index buffer for the results\n"
    "      //\\\"Creating a tempIndexBuffer\\\" .\n"
    "      indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "      // insert row from entry in temporary buffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "      assert\n"
    "    then\n"
    "\n"
    "    // move to next entry in the buffer\n"
    "    entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "    entry not if\n"
    "      // get next buffer from the current indexBuffer\n"
    "      indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "      indexBuffer if\n"
    "        entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      then\n"
    "    then\n"
    "\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rangeSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" ^indexPtr seitf -- )\n"
    "\n"
    "  0 0 0 locals| entry tempEntryBuffer indexBuffer seitf indexPtr upper lower key |\n"
    "\n"
    "  tp: rangeSelectIdxTask\n"
    "\n"
    "  seitf task::this task.seitf!\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  //\\\"Creating a tempIndexBuffer\\\" .\n"
    "  indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // get the indexBuffer looking for the lower key\n"
    "  lower indexPtr index.buffer ( indexBuffer )\n"
    "  to indexBuffer\n"
    "\n"
    "  // position in the index buffer at the lower key\n"
    "  lower indexBuffer indexPtr index.position\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "\n"
    "    // check against upper bound\n"
    "    upper entry indexPtr index.upper if\n"
    "\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        //\\\"Creating a tempIndexBuffer\\\" .\n"
    "        indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "         entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry beyond upper, null the entry and break from loop\n"
    "      0  to entry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  //\\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  //\\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* select for index ( called by lower_select_index request)                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": selectIndex ( \\\"<key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" \\\"<selectTaskRequest>\\\" \\\"<index>\\\" --  )\n"
    "\n"
    "  tp: selectIndex\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //\n"
    "  //assert::stack_5\n"
    "\n"
    "  0 0 0 0 0 0 locals| seitf selectTask rowCount indexBuffer entry\n"
    "    indexPtr indexNm selectTaskRequest upper lower key |\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  groupBy::new locals| pGroupBy |\n"
    "  pGroupBy groupBy.start\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index\n"
    "  indexNm find execute ( index^ )\n"
    "  to indexPtr\n"
    "\n"
    "  args.metadata if\n"
    "  metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  task::this task.seitf@ to seitf\n"
    "\n"
    "  // create the buffer queue in the seitf\n"
    "  //\\\"selectTask.queue\\\" queue::new execute task::this task.seitf@ seitf.bufferQueue!\n"
    "  \\\"selectTask.queue\\\" queue::new seitf seitf.bufferQueue!\n"
    "\n"
    "  // for each slot\n"
    "  grid.slots 0\n"
    "  do\n"
    "\n"
    "    args.metadata not if\n"
    "    I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    then\n"
    "\n"
    "    // put the partition in this tasks seitf\n"
    "    I seitf seitf.partition!\n"
    "\n"
    "    // create a selectTask to execute the key select on the index for the partition\n"
    "    key lower upper indexPtr seitf 5\n"
    "      selectTaskRequest nullptr \\\"selectTask\\\" TK_SELECT_PART spawnServerActor\n"
    "        to selectTask\n"
    "\n"
    "    1\n"
    "    begin\n"
    "    while  // first while\n"
    "      \n"
    "      begin\n"
    "        // attempt to pop buffer off the tasks buffer queue\n"
    "        seitf seitf.bufferQueue@  queue.pop ( value true | false )\n"
    "\n"
    "        // try again if no value\n"
    "        not while\n"
    "          //REQUST_LOOP2\n"
    "          //task.yield\n"
    "        args.sleep thread.sleep_ms\n"
    "      repeat\n"
    "      to indexBuffer\n"
    "\n"
    "      // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "      indexBuffer pGroupby groupBy.applyBuffer\n"
    "      // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "      //\\\"Popped tempEntryBuffer from buffer queue\\\" .\n"
    "      indexBuffer entryBuffer.firstEntry to entry\n"
    "\n"
    "      begin\n"
    "        entry\n"
    "        while // second while\n"
    "          \n"
    "          //\\\"Get an entry from the tempEntryBuffer\\\" .\n"
    "          display@ if\n"
    "            args.metadata if\n"
    "              entry entry.embeddedRow\n"
    "              I grid::toPartition\n"
    "              \\\"row: (%v '%v')\\\\n\\\" str.format .put\n"
    "            else\n"
    "              entry entry.embeddedRow \\\"\\\\n\\\" str.cat .put\n"
    "            then\n"
    "          then\n"
    "          1 rowCount + to rowCount\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      repeat  // end of second while\n"
    "\n"
    "      indexBuffer entryBuffer.isLast@ if\n"
    "        //\\\"Reached last buffer\\\" .\n"
    "        0\n"
    "      else\n"
    "        1  // no more entries, move to next buffer\n"
    "      then\n"
    "\n"
    "      indexBuffer entryBuffer.delete\n"
    "      //\\\"Deleted buffer\\\" .\n"
    "    repeat  // end of first while\n"
    "  loop\n"
    "\n"
    "  // delete the buffer queue from the seitf\n"
    "  seitf seitf.bufferQueue@ queue.delete\n"
    "  0 seitf seitf.bufferQueue!\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    rowCount seitf seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  rowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    "\n"
    "  pGroupBy groupBy.end\n"
    "  pGroupBy groupBy.delete\n"
    "\n"
    "  // + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + + +\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* range select for index ( called by rangeSelectTable request)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rangeSelectIdx2 ( ^indexPtr ^indexBuffer ^entry \\\"<lower>\\\" \\\"<upper>\\\"-- <entry> )\n"
    "\n"
    "  0 locals| row upper lower entry indexBuffer indexPtr |\n"
    "\n"
    "  tp: rangeSelectIdx\n"
    "\n"
    "  indexBuffer not if\n"
    "    0 to entry\n"
    "  else\n"
    "\n"
    "    entry not if\n"
    "      // position in the index buffer\n"
    "      lower indexBuffer indexPtr index.position\n"
    "      to entry\n"
    "    else\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "    then\n"
    "\n"
    "    entry not if\n"
    "\n"
    "      // we may not find an entry , so need to move to next buffer\n"
    "      indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "      indexBuffer not if\n"
    "        0 to entry\n"
    "      else\n"
    "        // get next entry from the current indexBuffer\n"
    "        entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      then\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  // return indexBuffer and entry\n"
    "  indexBuffer entry\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* range select cursor for index ( called by range_select_index request)      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": rangeSelectIndex2 ( \\\"<upper>\\\" \\\"<lower>\\\" \\\"<index>\\\" --  )\n"
    "\n"
    "  tp: rangeSelectIndex2\n"
    "\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //\n"
    "  assert::stack_3\n"
    "\n"
    "  0 0 0 0 locals| rowCount indexBuffer entry indexPtr indexNm lower upper |\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index\n"
    "  indexNm find execute ( index^ )\n"
    "  to indexPtr\n"
    "\n"
    "  args.metadata if\n"
    "    metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // for each slot\n"
    "  grid.slots 0\n"
    "  do\n"
    "\n"
    "    args.metadata not if\n"
    "      I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    then\n"
    "\n"
    "    // put the partition in this tasks seitf\n"
    "    I task::this task.seitf@ seitf.partition!\n"
    "\n"
    "    // get the indexBuffer at the lowerBound\n"
    "    lower indexPtr index.buffer ( indexBuffer )\n"
    "    to indexBuffer\n"
    "\n"
    "    1\n"
    "    begin\n"
    "\n"
    "      while\n"
    "\n"
    "      indexPtr indexBuffer entry lower upper\n"
    "      rangeSelectIdx2  ( indexPtr indexBuffer entry lower upper )\n"
    "      to entry\n"
    "      to indexBuffer\n"
    "\n"
    "      // check if entry is null ?\n"
    "      entry if\n"
    "        // check against upper bound\n"
    "        upper entry indexPtr index.upper\n"
    "        if\n"
    "          display@ if\n"
    "            args.metadata if\n"
    "              indexPtr entry entry.row row.string\n"
    "              I grid::toPartition\n"
    "              \\\"row: (%v '%v')\\\\n\\\" str.format .put\n"
    "            else\n"
    "              indexPtr entry entry.row row.string \\\"\\\\n\\\" str.cat .put\n"
    "            then\n"
    "          then\n"
    "          1 rowCount + to rowCount\n"
    "          1\n"
    "        else\n"
    "          0 to entry\n"
    "          0\n"
    "        then\n"
    "      else\n"
    "        0\n"
    "      then\n"
    "\n"
    "    repeat\n"
    "\n"
    "  loop\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    rowCount task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  rowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position scan select cursor for table (called by scanSelectIndex request)*/\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanSelectIdx ( ^indexPtr ^indexBuffer ^entry -- <entry> )\n"
    "\n"
    "  0 locals| row entry indexBuffer indexPtr |\n"
    "\n"
    "  tp: scanSelectIdx\n"
    "\n"
    "  indexBuffer not if\n"
    "    0 to entry\n"
    "  else\n"
    "\n"
    "    entry not if\n"
    "      // position in the index buffer\n"
    "      indexBuffer entryBuffer.firstEntry\n"
    "      to entry\n"
    "    else\n"
    "      // get next entry from the current indexBuffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "    then\n"
    "\n"
    "    entry not if\n"
    "      // we may not find an entry , so need to move to next buffer\n"
    "      indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "      indexBuffer not if\n"
    "        0 to entry\n"
    "      else\n"
    "        entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      then\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  // return indexBuffer and entry\n"
    "  indexBuffer entry\n"
    "\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* scan select for index ( called by scan_select_index request)               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanSelectIndex2 ( \\\"<index>\\\" --  )\n"
    "\n"
    "  \\\"scanSelectIndex (a)\\\" .\n"
    "\n"
    "  tp: scanSelectIndex\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //\n"
    "\n"
    "  assert::stack_1\n"
    "\n"
    "  0 0 0 0 locals| rowCount indexBuffer entry indexPtr sIndexNm |\n"
    "\n"
    "  \\\"scanSelectIndex (b)\\\" .\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index\n"
    "  sIndexNm find execute ( index^ )\n"
    "  to indexPtr\n"
    "\n"
    "  args.metadata if\n"
    "    metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // for each slot\n"
    "  grid.slots 0\n"
    "  do\n"
    "    args.metadata not if\n"
    "      I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    then\n"
    "\n"
    "    // put the partition in this tasks seitf\n"
    "    I task::this task.seitf@ seitf.partition!\n"
    "\n"
    "    // get the first indexBuffer\n"
    "    indexPtr index.positionFirst ( indexBuffer )\n"
    "    to indexBuffer\n"
    "\n"
    "    1\n"
    "    begin\n"
    "\n"
    "      while\n"
    "\n"
    "      indexPtr indexBuffer entry\n"
    "      scanSelectIdx  ( indexPtr indexBuffer entry )\n"
    "      to entry\n"
    "      to indexBuffer\n"
    "\n"
    "      // check if entry is null ?\n"
    "      entry if\n"
    "        display@ if\n"
    "          args.metadata if\n"
    "            indexPtr entry entry.row row.string\n"
    "            I grid::toPartition\n"
    "            \\\"row: (%v '%v')\\\\n\\\" str.format .put\n"
    "          else\n"
    "            indexPtr entry entry.row row.string \\\"\\\\n\\\" str.cat .put\n"
    "          then\n"
    "        then\n"
    "          1 rowCount + to rowCount\n"
    "          1\n"
    "      else\n"
    "        // null entry means done with this partition\n"
    "      0\n"
    "      then\n"
    "\n"
    "    repeat\n"
    "\n"
    "  loop\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    rowCount task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  rowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" ^indexPtr seitf -- )\n"
    "\n"
    "  0 0 0 locals| entry tempEntryBuffer indexBuffer seitf indexPtr upper lower key |\n"
    "\n"
    "  tp: scanSelectIdxTask\n"
    "\n"
    "  seitf task::this task.seitf!\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  \\\"Creating a tempIndexBuffer\\\" .\n"
    "  indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // position in the first index buffer\n"
    "  indexPtr index.positionFirst\n"
    "  to indexBuffer\n"
    "\n"
    "  // get the first entry in the buffer\n"
    "  indexBuffer entryBuffer.firstEntry\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    \\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    \\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        \\\"Creating a tempIndexBuffer\\\" .\n"
    "        indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    repeat\n"
    "\n"
    "  \\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  \\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove an index                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeIndex allParticipants 1 checkResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: removeIndex\n"
    "  locals| indexNm |\n"
    "\n"
    "  indexNm dup .\n"
    "  // forward reference :-(\n"
    "  \\\"indexTidyUp\\\" find execute\n"
    "\n"
    "  indexNm :forget\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set isUnique property of index                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": setIndexIsUnique allParticipants 2 checkResult ( \\\"<indexNm>\\\" true/false -- )\n"
    "\n"
    "  assert::stack_2\n"
    "\n"
    "  locals| sIndexNm bIsUnique |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  bIsUnique ( bIsUnique )\n"
    "\n"
    "    sIndexNm find execute ( bIsUnique index^ )\n"
    "\n"
    "  index.isUnique! ( )\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get size of index                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sizeIndex ( \\\"<indexNm>\\\" -- \\\"<size>\\\" )\n"
    "\n"
    "  find execute ( index^ )\n"
    "\n"
    "  index.space 0 swap number.magnitude >str\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position for upper select for table (called by upperSelectIndex request)   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": upperSelectIdx2 ( ^indexPtr ^indexBuffer ^entry -- <entry> )\n"
    "\n"
    "  0 locals| row entry indexBuffer indexPtr |\n"
    "\n"
    "  tp: upperSelectIdx\n"
    "\n"
    "  indexBuffer not if\n"
    "    0 to entry\n"
    "  else\n"
    "\n"
    "    entry not if\n"
    "     // position in the index buffer\n"
    "     indexBuffer entryBuffer.firstEntry\n"
    "     to entry\n"
    "   else\n"
    "      // get next entry from the current indexBuffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "    then\n"
    "\n"
    "    entry not if\n"
    "      // we may not find an entry , so need to move to next buffer\n"
    "      indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "      indexBuffer not if\n"
    "        0 to entry\n"
    "      else\n"
    "        entry indexBuffer entryBuffer.nextEntry to entry\n"
    "      then\n"
    "    then\n"
    "\n"
    "  then\n"
    "\n"
    "  // return indexBuffer and entry\n"
    "  indexBuffer entry\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* position key select cursor for table (called by selectIndex request)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": upperSelectIdxTask ( <\\\"key>\\\" \\\"<lower>\\\" \\\"<upper>\\\" ^indexPtr seitf -- )\n"
    "\n"
    "  0 0 0 locals| entry tempEntryBuffer indexBuffer seitf indexPtr upper lower key |\n"
    "\n"
    "  tp: rangeSelectIdxTask\n"
    "\n"
    "  seitf task::this task.seitf!\n"
    "\n"
    "  // create a temporary index buffer for the results\n"
    "  \\\"Creating a tempIndexBuffer\\\" .\n"
    "  indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "  // position in the first index buffer\n"
    "  indexPtr index.positionFirst\n"
    "  to indexBuffer\n"
    "\n"
    "  // get the first entry in the buffer\n"
    "  indexBuffer entryBuffer.firstEntry\n"
    "  to entry\n"
    "\n"
    "  // did we find an entry ?\n"
    "  entry not if\n"
    "\n"
    "    // mark this buffer as the last buffer\n"
    "    \\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "    tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "    // return the empty tempEntryBuffer\n"
    "    \\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "    tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // iterate thru the buffer till no more entries\n"
    "  begin\n"
    "  entry\n"
    "  while\n"
    "\n"
    "    // check against upper bound\n"
    "    upper entry indexPtr index.upper if\n"
    "\n"
    "      // insert row from entry in tempEntryBuffer\n"
    "      //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "      indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "\n"
    "      // check if we managed to insert the entry\n"
    "      not if\n"
    "        // buffer must be full\n"
    "        // put this tempEntryBuffer in seitf bufferQueue\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    "\n"
    "        // create another temporary index buffer for the results\n"
    "        \\\"Creating a tempIndexBuffer\\\" .\n"
    "        indexPtr entryBuffer::create to tempEntryBuffer\n"
    "\n"
    "        // insert row from entry in temporary buffer\n"
    "        //\\\"Inserting row into tempEntryBuffer\\\" .\n"
    "        indexPtr entry entry.row row.string tempEntryBuffer entryBuffer.insertRow\n"
    "        assert\n"
    "      then\n"
    "\n"
    "      // move to next entry in the buffer\n"
    "      entry indexBuffer entryBuffer.nextEntry to entry\n"
    "\n"
    "      entry not if\n"
    "        // get next buffer from the current indexBuffer\n"
    "        indexBuffer entryBuffer.nextBuffer to indexBuffer\n"
    "\n"
    "        indexBuffer if\n"
    "          entry indexBuffer entryBuffer.nextEntry to entry\n"
    "        then\n"
    "      then\n"
    "    else\n"
    "      // entry beyond upper, null the entry and break from loop\n"
    "      0  to entry\n"
    "    then\n"
    "  repeat\n"
    "\n"
    "  \\\"Marking tempEntryBuffer as last buffer\\\" .\n"
    "  // mark this buffer as the last buffer\n"
    "  tempEntryBuffer entryBuffer.isLast!\n"
    "\n"
    "  // put the buffer in the seitf bufferQueue\n"
    "  \\\"Appending tempEntryBuffer to buffer queue\\\" .\n"
    "  tempEntryBuffer seitf seitf.bufferQueue@ queue.append\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* upper select for index ( called by lower_select_index request)             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": upperSelectIndex ( \\\"<upper>\\\" \\\"<index>\\\" --  )\n"
    "\n"
    "  tp: upperSelectIndex\n"
    "  //\n"
    "  // execution context:\n"
    "  //   this task will have a seitf\n"
    "  //   and the seitf will have a table\n"
    "  //\n"
    "  assert::stack_2\n"
    "\n"
    "  0 0 0 0 locals| rowCount indexBuffer entry indexPtr indexNm upper |\n"
    "\n"
    "  // increment query count\n"
    "  queryCount ++\n"
    "\n"
    "  // push indexes\n"
    "  pushIndexes assert\n"
    "\n"
    "  // find the index\n"
    "  indexNm find execute ( index^ )\n"
    "  to indexPtr\n"
    "\n"
    "  args.metadata if\n"
    "    metadata@ \\\"metadata: %v\\\\n\\\" str.format .put\n"
    "  then\n"
    "\n"
    "  // for each slot\n"
    "  grid.slots 0\n"
    "  do\n"
    "\n"
    "    args.metadata not if\n"
    "      I grid::toPartition \\\"Partition: %v\\\\n\\\" str.format .put\n"
    "    then\n"
    "\n"
    "    // put the partition in this tasks seitf\n"
    "    I task::this task.seitf@ seitf.partition!\n"
    "\n"
    "    // get the first indexBuffer\n"
    "    indexPtr index.positionFirst ( indexBuffer )\n"
    "    to indexBuffer\n"
    "\n"
    "    1\n"
    "    begin\n"
    "\n"
    "      while\n"
    "\n"
    "      indexPtr indexBuffer entry\n"
    "      upperSelectIdx2  ( indexPtr indexBuffer entry upper )\n"
    "      to entry\n"
    "      to indexBuffer\n"
    "\n"
    "      // check if entry is null ?\n"
    "      entry if\n"
    "        // check against upper bound\n"
    "        upper entry indexPtr index.upper\n"
    "        if\n"
    "\n"
    "          display@ if\n"
    "            args.metadata if\n"
    "              indexPtr entry entry.row row.string\n"
    "              I grid::toPartition\n"
    "              \\\"row: (%v '%v')\\\\n\\\" str.format .put\n"
    "            else\n"
    "              indexPtr entry entry.row row.string \\\"\\\\n\\\" str.cat .put\n"
    "            then\n"
    "          then\n"
    "          1 rowCount + to rowCount\n"
    "          1\n"
    "        else\n"
    "          0 to entry\n"
    "          0\n"
    "        then\n"
    "      else\n"
    "       0\n"
    "      then\n"
    "\n"
    "    repeat\n"
    "\n"
    "  loop\n"
    "\n"
    "  // pop indexes\n"
    "  popIndexes\n"
    "\n"
    "  args.metadata if\n"
    "    rowCount task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"rows selected\\\"  rowCount \\\"%v %v\\\\n\\\" str.format .put\n"
    "  then\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT index.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of indexColumn.sen
  sDefinition =
    "\""
    "\\\"munged indexColumn.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* indexColumn.sen -- index column related words                              */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"indexColumn.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* indexColumn is used as a kind of word to identify index columns            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": indexColumn: ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make the index columns sub folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeIndexColumns ( \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  find execute ( dic )\n"
    "  index.subDic pathPush \\\"columns\\\" :dic drop pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check within index columns folder                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": withinIndexColumns\n"
    "    0 pathPick dic.name \\\"columns\\\" str.equal\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check in indexes columns folder                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkInIndexColumns\n"
    "    withinIndexColumns if true exit then\n"
    "    EC_NOT_IN_COLUMNS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* find the index column folder and push it onto task dictionary              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pushIndexColumns ( -- )\n"
    "\n"
    "    \\\"columns\\\" checkIsWord\n"
    "    not if EC_NO_COLUMNS_DIC false exit then\n"
    "    execute pathPush\n"
    "    true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* pop the index column folder                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": popIndexColumns\n"
    "    pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create index column as a constant                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :indexColumn ( \\\"<columnName>\\\" )\n"
    "    :constant\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check and add an index column                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkAddIndexColumn ( \\\"<columnName>\\\" \\\"<indexNm>\\\" \\\"<tableNm>\\\" -- true | eEC false )\n"
    "\n"
    "  locals| tableNm indexNm columnNm |\n"
    "\n"
    "  // check we are in the indexes folder\n"
    "  checkInIndexes not if false exit then\n"
    "\n"
    "  // move out of the indexes folder temporarily\n"
    "  popIndexes\n"
    "\n"
    "  // push the table sub folder\n"
    "  tableNm pushTableSub assert\n"
    "\n"
    "  // push the table columns folder\n"
    "  pushColumns\n"
    "\n"
    "  // look for the index column in the table columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should exist in table\n"
    "  not if EC_INVALID_COLUMN false popColumns popTableSub pushIndexes assert exit then\n"
    "\n"
    "  // pop the columns folder\n"
    "  popColumns\n"
    "\n"
    "  // pop the tables sub folder\n"
    "  popTableSub\n"
    "\n"
    "  // push back the indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // push the index sub folder\n"
    "  indexNm\n"
    "  pushIndexSub assert   // not if false exit then\n"
    "\n"
    "  // push the index columns folder\n"
    "  pushIndexColumns assert // not if false exit then\n"
    "\n"
    "  // look for the column in the indexes columns\n"
    "  columnNm findInCurrent\n"
    "\n"
    "  // column should not already exist\n"
    "  if EC_DUPLICATE_COLUMN false popIndexColumns popIndexSub exit then\n"
    "\n"
    "  //pop the index columns folder\n"
    "  popIndexColumns\n"
    "\n"
    "  // pop the index sub folder\n"
    "  popIndexSub\n"
    "\n"
    "  assertInIndexes\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list columns of an index                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": listIndexColumns ( \\\"<indexNm>\\\" -- list )\n"
    "\n"
    "  find execute ( ^indexPtr )\n"
    "\n"
    "  0 locals| indexCols indexPtr |\n"
    "\n"
    "  indexPtr index.columnCount to indexCols\n"
    "\n"
    "  \\\"\\\"                             // initial ls string\n"
    "  args.metadata if\n"
    "    indexCols 0 do\n"
    "      I indexPtr index.columnType\n"
    "      I indexPtr index.columnName\n"
    "      \\\"row: ('%v', '%v')\\\\n\\\" str.format\n"
    "      str.cat\n"
    "    loop\n"
    "    indexCols task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "\n"
    "    indexCols 0 do\n"
    "      I indexPtr index.columnType\n"
    "      I indexPtr index.columnName\n"
    "      \\\"%v %v \\\" str.format\n"
    "      I 1 + indexCols < if\n"
    "        swap \\\", \\\" str.cat\n"
    "      then\n"
    "      str.cat\n"
    "    loop\n"
    "  then\n"
    "\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column (called by addIndexColumn)                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": add_indexColumn ( \\\"<columnNm>\\\" \\\"<indexNm>\\\" -- )\n"
    "\n"
    "  0 locals| indexPtr indexNm columnNm |\n"
    "\n"
    "  // push the index sub folder\n"
    "  indexNm\n"
    "  pushIndexSub assert\n"
    "\n"
    "  // push index columns folder\n"
    "  pushIndexColumns assert\n"
    "\n"
    "  columnNm columnNm    ( \\\"<columnNm>\\\" \\\"<columnNm>\\\" )\n"
    "  :indexColumn\n"
    "\n"
    "  // pop index columns folder\n"
    "  popIndexColumns\n"
    "\n"
    "  // pop the index sub folder\n"
    "  popIndexSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column (run by all participants)                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": addIndexColumn allParticipants 2 checkResult ( \\\"<columnNm>\\\" \\\"<indexNm>\\\" -- <result> )\n"
    "\n"
    "  0 locals| indexPtr indexNm columnNm |\n"
    "\n"
    "  args.tracepoint if\n"
    "    \\\"ADDING COLUMN \\\" indexNm str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  tp: addingIndexColumn\n"
    "\n"
    "  columnNm indexNm add_indexColumn\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create the column vector of the index                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": columnVecIndex allParticipants 1 checkResult ( \\\"<indexNm>\\\" -- true n# true )\n"
    "\n"
    "  0 locals| indexPtr indexNm |\n"
    "\n"
    "  //\\\"columnVecIndex\\\" . indexNm .\n"
    "\n"
    "  // get index ptr\n"
    "  indexNm findInCurrent execute to indexPtr\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // double check we can see the index\n"
    "  //indexPtr find execute stk drop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  // push the index sub dic and then the columns sub dic\n"
    "  indexNm pushIndexSub assert\n"
    "\n"
    "  pushIndexColumns assert\n"
    "\n"
    "  // double check the path\n"
    "  //task::this task.dicStack dicPath.dump\n"
    "\n"
    "  // iterate contents of columns dictionary \n"
    "  0 pathPick dic.lastWord dup\n"
    "  iterate                        // iterate word cursor\n"
    "    object@ execute              ( value )\n"
    "    object@ word.name            ( value wordNm )\n"
    "    indexPtr                     ( value wordNm ^table )\n"
    "    index.createColumnVec\n"
    "    object@ word.prev object!    // advance cursor backwards thru words\n"
    "  next\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "\n"
    "  //indexPtr index.showColumnVec\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  popIndexColumns\n"
    "\n"
    "  popIndexSub\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT indexColumn.sen"_Str
  ;

  vCompileConstant(sDefinition);

