  // munge of loader.sen
  sDefinition =
    "\""
    "\\\"munged loader.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* loader.sen -- Parallel Table Loader                                        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"loader.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* loading timer                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "timer: loadTimer\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a loader using name on the stack (leaves loader on stack)           */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :loader\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_loader allot\n"
    "  word.this >body object.magic!\n"
    "  CN_LOADER word.this >body object.class!\n"
    "  word.this >body loader.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* parallel loading of file into table                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableLoader ( \\\"<path>\\\" \\\"<tableNm>\\\" -- t|f )\n"
    "\n"
    "  assert::stack_2 ( \\\"<path>\\\" \\\"<tableNm>\\\" )\n"
    "  0 locals| pSubTask stableNm sPath |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // check if path file exists                                 //! refactor this\n"
    "\n"
    "  file::new locals| fp |\n"
    "  sPath fp file.path!\n"
    "\n"
    "  OPEN_READ fp file.open ( t|f )\n"
    "  not if\n"
    "    fp file.delete assert::stack_0 EC_INVALID_FILE false exit\n"
    "  then\n"
    "\n"
    "  fp file.close fp file.delete assert::stack_0\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create table loader\n"
    "\n"
    "  // start load timer\n"
    "  loadTimer timer.start\n"
    "\n"
    "  // create table loader\n"
    "  \\\"__table_loader\\\" find dup if else\n"
    "    drop\n"
    "    \\\"__table_loader\\\" :loader\n"
    "  then\n"
    "  execute locals| tblLoader | assert::stack_0\n"
    "\n"
    "  // initialise table loader\n"
    "  sTableNm find execute locals| tablePtr |\n"
    "  tablePtr tblLoader loader.table!\n"
    "  sPath tblLoader loader.path!\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create sub loaders\n"
    "\n"
    "  // begin a transaction\n"
    "  beginTransaction tblLoader loader.txref!\n"
    "\n"
    "  //REQUEST_LOOP2\n"
    "  // hold task mutex while we create sub loaders\n"
    "  //task::this grabMutex\n"
    "\n"
    "  N_SERVER_THREADS setAcks\n"
    "\n"
    "  N_SERVER_THREADS 0 do\n"
    "\n"
    "    << tblLoader loader.newSub >>\n"
    "\n"
    "    pathGet >>\n"
    "\n"
    "    1 \\\"loadSub\\\" task::this I >loadSubNm TK_LOADSUB_SERVER spawnServerActor to pSubTask\n"
    "\n"
    "  loop\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // break file into chunks (this causes sub loaders to load them)\n"
    "\n"
    "  // using table loader scan thru the file and find chunks for sub loaders\n"
    "  begin tblLoader loader.findChunk while repeat\n"
    "\n"
    "  // now wait for sub loaders to complete (drops mutex for duration)\n"
    "  ackWait\n"
    "\n"
    "  // at this point all sub loaders have completed and mutex was regrabbed\n"
    "\n"
    "  //REQUEST_LOOP2\n"
    "  // drop mutex\n"
    "  //task::this dropMutex\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // tidy up\n"
    "\n"
    "  // commit the transaction\n"
    "  commitTransaction\n"
    "\n"
    "  // destroy Loader\n"
    "  \\\"__table_loader\\\" find word.forget\n"
    "\n"
    "  // print timing\n"
    "  loadTimer timer.update\n"
    "  \\\"Load time \\\" .put\n"
    "  loadTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* loading of stream into table                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableLoaderStream ( \\\"<path>\\\" ^table -- t|f )\n"
    "\n"
    "  // check if path file exists\n"
    "  swap file::new >r\n"
    "  dup r0 file.path!\n"
    "  OPEN_READ r0 file.open\n"
    "  if r0 file.close rdrop swap else rdrop drop drop EC_INVALID_FILE false exit then\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  file::new >reg0         // reg0 - file\n"
    "  >reg1                  // reg1 - table\n"
    "  >reg2                  // reg2 - path\n"
    "  rowBuffer::new >reg3    // reg3 - rowbuffer\n"
    "  beginTransaction >reg4 // reg4 - txref\n"
    "  0 >regF                // regF - counter\n"
    "\n"
    "  reg2 reg0 file.path!\n"
    "  OPEN_READ reg0 file.open drop\n"
    "\n"
    "  loadTimer timer.start\n"
    "\n"
    "  begin\n"
    "    reg0 file.read\n"
    "    while\n"
    "      reg4 reg3 rowbuffer.append\n"
    "      not if\n"
    "        reg3 0 reg1 table.appendBuffer\n"
    "        rowBuffer::new >reg3\n"
    "        reg4 reg3 rowbuffer.append\n"
    "        drop\n"
    "      then\n"
    "\n"
    "      regF 1+ dup >regF\n"
    "      100000 % not if regF . then\n"
    "  repeat\n"
    "\n"
    "  reg3 0 reg1 table.appendBuffer\n"
    "\n"
    "  loadTimer timer.update\n"
    "\n"
    "  \\\"Load time \\\" .put\n"
    "  loadTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "\n"
    "  reg0 file.close\n"
    "\n"
    "  reg0 file.delete\n"
    "\n"
    "  reg.pop\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* loading of stream into table                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": tableLoaderStream2 ( \\\"<path>\\\" ^table -- t|f )\n"
    "\n"
    "  find execute ( \\\"filename\\\" table )\n"
    "\n"
    "  // check if path file exists\n"
    "  swap file::new >r\n"
    "  dup r0 file.path!\n"
    "  OPEN_READ r0 file.open\n"
    "  if r0 file.close rdrop swap else rdrop drop drop EC_INVALID_FILE false exit then\n"
    "\n"
    "  reg.push\n"
    "\n"
    "  file::new >reg0         // reg0 - file\n"
    "  >reg1                  // reg1 - table\n"
    "  >reg2                  // reg2 - path\n"
    "  rowBuffer::new >reg3    // reg3 - rowbuffer\n"
    "  beginTransaction >reg4 // reg4 - txref\n"
    "  0 >regF                // regF - counter\n"
    "\n"
    "  reg2 reg0 file.path!\n"
    "  OPEN_READ reg0 file.open drop\n"
    "\n"
    "  loadTimer timer.start\n"
    "\n"
    "  begin\n"
    "    reg0 file.readRecord\n"
    "    while\n"
    "      reg0 reg4 reg3 rowbuffer.appendRecord\n"
    "      not if\n"
    "        reg3 0 reg1 table.appendBuffer\n"
    "        rowBuffer::new >reg3\n"
    "        reg0 reg4 reg3 rowbuffer.appendRecord\n"
    "        drop\n"
    "      then\n"
    "\n"
    "      regF 1+ dup >regF\n"
    "      100000 % not if task.yield then\n"
    "  repeat\n"
    "\n"
    "  reg3 0 reg1 table.appendBuffer\n"
    "\n"
    "  loadTimer timer.update\n"
    "\n"
    "  \\\"Load time \\\" .put\n"
    "  loadTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "\n"
    "  reg0 file.close\n"
    "\n"
    "  reg0 file.delete\n"
    "\n"
    "  reg.pop\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT loader.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of loaderSub.sen
  sDefinition =
    "\""
    "\\\"munged loaderSub.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* loaderSub.sen -- Parallel Table Loader Sub                                 */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"loaderSub.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a sub loader using name on the stack (leaves loader on stack)       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :loaderSub\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_loader allot\n"
    "  word.this >body object.magic!\n"
    "  CN_LOADERSUB word.this >body object.class!\n"
    "  word.this >body loaderSub.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form loader sub name                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >loadSubNm ( i -- s )\n"
    "\n"
    "  \\\"sl\\\" swap >str str.cat \\\".task\\\" str.cat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* form partition task name                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >partitionTaskNm ( i -- s )\n"
    "\n"
    "  \\\"PT\\\" swap >str str.cat \\\".task\\\" str.cat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* append row buffer to partition of given named table                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadAppendBuffer$ ( rowBuffer partitionNo \\\"<tableNm>\\\" -- true )\n"
    "\n"
    "tp: loadAppendBuffer$\n"
    "  0 locals| pTable sTableNm iPartitionNo pRowBuffer pLoaderSub |\n"
    "\n"
    "  // why:\n"
    "  //   loaderSub has forwarded a full rowBuffer which needs to be\n"
    "  //   appended to partition of table\n"
    "\n"
    "  // where:\n"
    "  //   in participant task running pLoop on participant thread;\n"
    "\n"
    "  // what:\n"
    "  //   find named table to get pointer to table\n"
    "  //   then append row buffer to partition of table\n"
    "\n"
    "  1 task::this task.thread thread.name@ str.left \\\"p\\\" str.equal assert\n"
    "\n"
    "  args.tracepoint if\n"
    "    sTableNm \\\"APPENDING ROWBUFFER \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  // get ^table\n"
    "  sTableNm find execute ( rb ptn table )\n"
    "  to pTable\n"
    "\n"
    "  pRowBuffer iPartitionNo  pTable    ( rb ptn tablePtr )\n"
    "\n"
    "tp: tp1\n"
    "  3 \\\"partitionAppendBuffer\\\" iPartitionNo grid::toSlot dup >partitionTaskNm\n"
    "  TK_LOADSUB_PART\n"
    "\n"
    "tp: tp2\n"
    "  spawnPartitionActor\n"
    "\n"
    "tp: tp3\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* forward append of rowbuffer to participant for partition                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ~loadAppendBuffer ( -- )\n"
    "\n"
    "tp: ~loadAppendBuffer\n"
    "\n"
    "   locals| pLoaderSub |\n"
    "\n"
    "  // why:\n"
    "  //   loaderSub has a full rowBuffer which needs to be sent to participant\n"
    "  //   to be appended to partition of table\n"
    "\n"
    "  // where:\n"
    "  //   in loadSub task running loadSub on general thread;\n"
    "  //   parent task is req.task running tableLoader;\n"
    "  //   reg0 has ^loaderSub\n"
    "\n"
    "  // what:\n"
    "  //   we need to have the coordinator send the loadAppendBuffer$ indirect call\n"
    "  //   to the participant via a sendParticipant call\n"
    "\n"
    "  //13 task::this task.thread thread.name@ str.left \\\"generalThread\\\" str.equal assert\n"
    "  task.parent@ task.name@ \\\"req.task\\\" str.equal assert\n"
    "\n"
    "  //\n"
    "  // a) form the indirect call of loadAppendBuffer\n"
    "  //\n"
    "\n"
    "  <<\n"
    "    pLoaderSub loaderSub.rowBuffer           ( << rb )\n"
    "    nullPtr pLoaderSub loaderSub.rowBuffer!  // set working row buffer to null\n"
    "    pLoaderSub loaderSub.partition           ( << rb ptn )\n"
    "    pLoaderSub loaderSub.table table.name    ( << rb ptn \\\"<tableNm>\\\" )\n"
    "    \\\"loadAppendBuffer$\\\"                      ( << rb ptn \\\"<tableNm>\\\" \\\"loadAppendBuffer$\\\" )\n"
    "\n"
    "tp: theIndirectCall\n"
    "\n"
    "  >>                       ( <<loadAppendBuffer$>> )\n"
    "\n"
    "  //\n"
    "  // b) <<loadAppendBuffer$>> to be forwarded to one participant\n"
    "  //    via sendParticipant in the coordinatoor\n"
    "  //\n"
    "\n"
    "  // to which node/participant\n"
    "  pLoaderSub loaderSub.hashPartition  ( <<loadAppendBuffer$>> node )\n"
    "\n"
    "  // forward to coordinator and wait\n"
    "  >>oneParticipant> ( bool )\n"
    "\n"
    "tp: theIndirectResult\n"
    "\n"
    "  // we expect loadAppendBuffer$ to return true\n"
    "  //assert\n"
    "\n"
    "  checkResult\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* parallel sub-loading of file into table                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": loadSub ( ^loaderSub -- )\n"
    "\n"
    "  // this is being run by a general thread on the originator node\n"
    "\n"
    "  // first set the taskset in this task\n"
    "  // needed when being resumed by coordinator\n"
    "  0 0 0 locals| iPartitionNo ploaderSub iTotalPartitions |\n"
    "\n"
    "  task::this task.thread thread.taskset@\n"
    "  task::this task.taskset!\n"
    "\n"
    "  // expand dic stack valset and set\n"
    "  valset> drop dicPath.set\n"
    "\n"
    "  // expand args valset\n"
    "  valset> drop\n"
    "  to pLoaderSub\n"
    "\n"
    "  // get table, tx and load map from parent loader\n"
    "  //   open the chunked file\n"
    "  //   read first chunk\n"
    "  pLoaderSub loaderSub.begin\n"
    "\n"
    "  // load each record\n"
    "  begin\n"
    "\n"
    "    // attempt to fetch next record from file\n"
    "    pLoaderSub loaderSub.fetchRecord\n"
    "\n"
    "    // process record\n"
    "    while\n"
    "\n"
    "      pLoaderSub loaderSub.validateRow if\n"
    "\n"
    "        // hash the record to get partition\n"
    "        pLoaderSub loaderSub.hashRecord\n"
    "\n"
    "        // attempt to insert record as row into working buffer for partition\n"
    "        pLoaderSub loaderSub.insertRow\n"
    "\n"
    "        // was buffer full?\n"
    "        not if\n"
    "\n"
    "        //\\\"BUFFER FULL\\\" .\n"
    "        tp: bufferFull\n"
    "\n"
    "          // append row buffer to table/partition/strand\n"
    "          pLoaderSub ~loadAppendBuffer\n"
    "\n"
    "          // insert row into new working buffer\n"
    "          pLoaderSub loaderSub.insertRow assert\n"
    "\n"
    "        then // if buffer full\n"
    "\n"
    "      then // if row valid\n"
    "\n"
    "  repeat // for all records in chunked file\n"
    "\n"
    "  // calculate total partitions in the cluster\n"
    "  grid.slots grid.nodes *\n"
    "  to iTotalPartitions\n"
    "\n"
    "  // check for dangling buffers\n"
    "  iTotalPartitions 0 do\n"
    "\n"
    "    // set the partition we are using\n"
    "    I pLoaderSub loaderSub.partition!\n"
    "\n"
    "    // test for a dangling row buffer for parition I\n"
    "    pLoaderSub loaderSub.rowBuffer\n"
    "    if\n"
    "      // append row buffer to table/partition/strand\n"
    "      pLoaderSub ~loadAppendBuffer\n"
    "\n"
    "    then\n"
    "\n"
    "  loop\n"
    "\n"
    "  // close the file\n"
    "  pLoaderSub loaderSub.end\n"
    "\n"
    "  // this sub has completed, ack the parent loader\n"
    "  task::this task.name@ \\\"%v acking parent\\\" str.format .\n"
    "  task.parent@ ack\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* partition task appends the row buffer to the table                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": partitionAppendBuffer ( rowBuffer partitionNo table^ -- )\n"
    "\n"
    "tp: partitionAppendBuffer\n"
    "  locals| pTable iPartitionNo pRowBuffer |\n"
    "\n"
    "  pRowBuffer iPartitionNo pTable table.appendBuffer ( )\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT loaderSub.sen"_Str
  ;

  vCompileConstant(sDefinition);

