    "/* spawn the monitor drone                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnMonitorDrone\n"
    "\n"
    "  0 \\\"monitorLoop\\\" \\\"MonitorDrone\\\" TK_MONITOR_DRONE spawnDroneActor drop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* monitor task loop                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": monitorLoop\n"
    "\n"
    "//\\\"monitorDrone\\\" task::this task.name!\n"
    "\n"
    "  monitorDronePrint if\n"
    "    task::this task.name@ \\\" running...\\\" str.cat .\n"
    "  then\n"
    "\n"
    "  \\\"\\\" sMonitorString !\n"
    "\n"
    "  begin\n"
    "\n"
    "    zMonitorLock lock.grabWrite\n"
    "\n"
    "      \\\"freespace \\\" bp::freeSpace >str str.cat\n"
    "\n"
    "      \\\" queries \\\" str.cat\n"
    "\n"
    "      queryCount @ >str str.cat\n"
    "\n"
    "      sMonitorString !\n"
    "\n"
    "    zMonitorLock lock.dropWrite\n"
    "\n"
    "    // sMonitorString @ .\n"
    "\n"
    "    monitorDronePrint if bp::analyze then\n"
    "\n"
    "  10 thread.sleep_s\n"
    "\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get monitor string                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "\n"
    ": MonitorString@\n"
    "\n"
    "  zMonitorLock lock.grabRead\n"
    "\n"
    "    sMonitorString @\n"
    "\n"
    "  zMonitorLock lock.dropRead\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT monitorDrone.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of munge.sen
  sDefinition =
    "\""
    "\\\"munged munge.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* munge.sen -- create the .cpp from .sen                                     */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"munge.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write the .cpp header portion of the file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeCppHeader\n"
    "\n"
    "  locals| cppFile |\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  cppFile file.write \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"/* MungedSen.cpp - munged sen files                                           */\\\"\n"
    "  cppFile file.write \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  cppFile file.write \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"#include \\\\\\\"StorageEngine.h\\\\\\\"\\\\n\\\" cppFile file.write\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "  \\\"void Task::vAddMunged(MP_Task mpTask)\\\\n\\\" cppFile file.write\n"
    "  \\\"{\\\\n\\\" cppFile file.write\n"
    "  \\\"  s48K sDefinition;\\\\n\\\" cppFile file.write\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put the variable for the sen file into c++ file                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeCppVariable ( cppFile senFile -- )\n"
    "\n"
    "  locals| senFile cppFile |\n"
    "\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"  // munge of \\\" cppFile file.write\n"
    "    senFile file.path@ cppFile file.write\n"
    "    \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"  sDefinition =\\\\n\\\" cppFile file.write\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put the variable initialise into c++ file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeSenText ( cppFile senFile -- )\n"
    "\n"
    "  \\\"\\\" locals| senLine senFile cppFile |\n"
    "\n"
    "  \\\"    \\\\\\\"\\\\\\\\\\\\\\\"\\\\\\\"\\\\n\\\"   cppFile file.write\n"
    "\n"
    "  \\\"    \\\\\\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\"munged \\\" cppFile file.write\n"
    "  senFile file.path@ cppFile file.write\n"
    "  \\\"\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\" .verbose \\\\\\\\n\\\\\\\"\\\\n\\\" cppFile file.write    // change this to verbose\n"
    "\n"
    "  begin senFile file.read while\n"
    "\n"
    "    str.escape str.escape to senLine\n"
    "\n"
    "    senLine \\\";\\\" str.equal if\n"
    "      \\\" ;\\\" to senLine\n"
    "    then\n"
    "\n"
    "    \\\"    \\\\\\\"\\\"  cppFile file.write\n"
    "    senLine   cppFile file.write\n"
    "    \\\"\\\\\\\\n\\\\\\\"\\\"   cppFile file.write\n"
    "    \\\"\\\\n\\\"      cppFile file.write\n"
    "\n"
    "  repeat\n"
    "\n"
    "  \\\"    \\\\\\\"\\\\\\\\\\\\\\\"\\\\\\\"\\\\n\\\"   cppFile file.write\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put the variable for the sen file into c++ file                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeSenConstant ( cppFile senFile -- )\n"
    "\n"
    "  locals| senFile cppFile |\n"
    "\n"
    "  \\\"  \\\\\\\" CONSTANT \\\" cppFile file.write\n"
    "  senFile file.path@ cppFile file.write\n"
    "  \\\"\\\\\\\"_Str\\\\n\\\" cppFile file.write\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* put a ; terminator for statement into c++ file                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeCppTerm ( cppFile senFile -- )\n"
    "\n"
    "  locals| senFile cppFile |\n"
    "\n"
    "  \\\"  ;\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"  vCompileConstant(sDefinition);\\\\n\\\" cppFile file.write\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* write the .cpp footer portion of the file                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeCppFooter\n"
    "\n"
    "  locals| cppFile |\n"
    "\n"
    "  \\\"}\\\\n\\\" cppFile file.write\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  cppFile file.write\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"/* end                                                                        */\\\"\n"
    "  cppFile file.write\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    "\n"
    "  \\\"/*============================================================================*/\\\"\n"
    "  cppFile file.write\n"
    "  \\\"\\\\n\\\" cppFile file.write\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* produce a c++ statement for the sen file                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeCppStatement ( cppFile senFile -- )\n"
    "\n"
    "  locals| senFile cppFile |\n"
    "\n"
    "  cppFile senFile mungeCppVariable\n"
    "\n"
    "  cppFile senFile mungeSenText\n"
    "\n"
    "  cppFile senFile mungeSenConstant\n"
    "\n"
    "  cppFile senFile mungeCppTerm\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge one .sen file                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeSenFile ( \\\"<fileNm\\\"> cppFile -- )\n"
    "\n"
    "  file::new locals| senFile cppFile |\n"
    "\n"
    "  senFile file.path!\n"
    "\n"
    "  OPEN_READ senFile file.open assert\n"
    "\n"
    "  cppFile senFile mungeCppStatement\n"
    "\n"
    "  // close and delete the file accessor\n"
    "  senFile file.close\n"
    "  senFile file.delete\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files in the sen dir                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": mungeDir ( cppFile senDir -- )\n"
    "\n"
    "  locals| senDir cppFile |\n"
    "\n"
    "  // read thru directory\n"
    "  begin senDir dir.read while\n"
    "\n"
    "    // ignore entries which aren't regular files\n"
    "    senDir dir.entryType DE_REG == not continue\n"
    "\n"
    "    // ignore entries which aren't .sen files\n"
    "    4 senDir dir.entryName str.right \\\".sen\\\" str.equal not continue\n"
    "    senDir dir.entryName .\n"
    "\n"
    "    // convert to C++\n"
    "    senDir dir.entryName cppFile mungeSenFile\n"
    "\n"
    "  repeat\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* munge all .sen files                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": munge\n"
    "\n"
    "  // create a directory accessor\n"
    "  file::new dir::new \\\"\\\" locals| origDir senDir cppFile |\n"
    "\n"
    "  // save original dir and change to ../Sen\n"
    "  dir.getCurrent to OrigDir\n"
    "\n"
    "  \\\"../Sen\\\" dir.changeCurrent\n"
    "  dir.getCurrent \\\"Current working directory now: %v\\\" str.format .\n"
    "\n"
    "  // set path in the sen directory accessor\n"
    "  \\\".\\\" senDir dir.path!\n"
    "\n"
    "  // open sen directory\n"
    "  senDir dir.open assert\n"
    "\n"
    "  // open cpp file\n"
    "  \\\"../Munge/Task_AddMunged.cpp\\\" cppFile file.path!\n"
    "  OPEN_WRITE cppFile file.open assert\n"
    "\n"
    "  cppFile mungeCppHeader\n"
    "\n"
    "  // munge the command dir\n"
    "  cppFile senDir mungeDir\n"
    "\n"
    "  cppFile mungeCppFooter\n"
    "\n"
    "  // close and delete file accessor\n"
    "  cppFile file.close\n"
    "  cppFile file.delete\n"
    "\n"
    "  // close and delete directory accessor\n"
    "  senDir dir.close\n"
    "  senDir dir.delete\n"
    "\n"
    "  // change back to original dir\n"
    "  origDir dir.changeCurrent\n"
    "  dir.getCurrent \\\"Current working directory now: %v\\\" str.format .\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT munge.sen"_Str
  ;

