    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* reclaim task loop                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": iterateSEitfList\n"
    "\n"
    "  seitfcrs seitfcrs seitfcursor.begin\n"
    "\n"
    "  iterate\n"
    "\n"
    "    reclaimDronePrint if\n"
    "      object@ seitf.dump\n"
    "    then\n"
    "\n"
    "    object@ task::this task.seitf!\n"
    "      object@ seitf.pid\n"
    "      0 task::this task.seitf!\n"
    "\n"
    "    reclaimDronePrint if\n"
    "      dup .put \\\" \\\" .put dup process.testpid .put .\\\\n\n"
    "    then\n"
    "\n"
    "    process.testpid not if\n"
    "      reclaimDronePrint if\n"
    "        \\\"deleting...\\\" .\n"
    "      then\n"
    "      object@\n"
    "      cursor@ seitfcursor.end 0 object!\n"
    "      seitf.delete\n"
    "    else\n"
    "      reclaimDronePrint if\n"
    "        \\\"not deleteing\\\" .\n"
    "      then\n"
    "      cursor@ seitfcursor.next object!\n"
    "    then\n"
    "\n"
    "  next\n"
    "\n"
    "  seitfcrs seitfcursor.end\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* reclaim task loop                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": reclaimLoop\n"
    "\n"
    "//\\\"reclaimTask\\\" task::this task.name!\n"
    "\n"
    "  reclaimDronePrint if\n"
    "    task::this task.name@ \\\" running...\\\" str.cat .\n"
    "  then\n"
    "\n"
    "  \\\"\\\" sReclaimString !\n"
    "\n"
    "  begin\n"
    "\n"
    "    zReclaimLock lock.grabWrite\n"
    "\n"
    "    iterateSEitfList\n"
    "\n"
    "    zReclaimLock lock.dropWrite\n"
    "\n"
    "    // sReclaimString @ .\n"
    "\n"
    "    3 thread.sleep_s\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get reclaim string                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sReclaimString@\n"
    "\n"
    "  zReclaimLock lock.grabRead\n"
    "\n"
    "    sReclaimString @\n"
    "\n"
    "  zReclaimLock lock.dropRead\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT reclaimDrone.sen"_Str
  ;

