  // munge of requests_basics.sen
  sDefinition =
    "\""
    "\\\"munged requests_basics.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_basics.sen -- the set of requests supported by requestTask        */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"requests_basics.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return an error response                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": <NIP+ERROR> ( ... errorCode -- errrorStr errorCode 2 )\n"
    "\n"
    "  // discard all but top item on stack\n"
    "  nipAll\n"
    "\n"
    "  // error code should be left on stack\n"
    "  assert::stack_1\n"
    "  CN_INTVAL assert::class\n"
    "\n"
    "  // convert error code into error string\n"
    "  dup error.msg ( errorCode errorStr )\n"
    "\n"
    "  // bring error code to top\n"
    "  swap ( errorStr errorCode )\n"
    "\n"
    "  // there are two return arguments\n"
    "  2 ( errorStr errorCode 2 )\n"
    "\n"
    "  ddlLock::testDrop\n"
    "\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return a success response                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": <SUCCESS> ( str -- str 0 2 )\n"
    "\n"
    "  // a string as a return value should be on stack\n"
    "  assert::stack_1\n"
    "  CN_STRVAL assert::class\n"
    "\n"
    "  // push 0 to indicate success / no error\n"
    "  0\n"
    "\n"
    "  // there are two return arguments\n"
    "  2\n"
    "\n"
    "  ddlLock::testDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return an OK response                                                      */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": <OK> ( -- \\\"<ok>\\\" 0 2 )\n"
    "\n"
    "  // the stack should be empty\n"
    "  assert::stack_0\n"
    "\n"
    "  // push \\\"<ok>\\\" as the return str\n"
    "  \\\"<ok>\\\"\n"
    "\n"
    "  // push 0 to indicate success / no error\n"
    "  0\n"
    "\n"
    "  // there are two return arguments\n"
    "  2\n"
    "\n"
    "  ddlLock::testDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print class counts (helper for snapshot)                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": printClassCounts\n"
    "\n"
    "  0 do\n"
    "    dup 0 != if\n"
    "      I class.name \\\"%v %v\\\" str.format .\n"
    "    else\n"
    "     drop\n"
    "    then\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check system has enough buffers                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkEnoughBuffers\n"
    "\n"
    "  // return true if enough buffers, others return error code\n"
    "  bp::freeBuffers 100 >\n"
    "  if\n"
    "    true exit\n"
    "  else\n"
    "    EC_LOW_BUFFERS false\n"
    "  then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_basics.sen"_Str
  ;

  vCompileConstant(sDefinition);

