    ": add_column ( \\\"<columnTy>\\\" \\\"<sColumnNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "\n"
    "  locals| sTableNm sColumnNm |\n"
    "\n"
    "  sColumnNm sTableNm\n"
    "  checkAddColumn not if <NIP+ERROR> exit then\n"
    "\n"
    "  sColumnNm sTableNm\n"
    "  addColumn ( ) assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add an index column                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": add_idxcolumn ( \\\"<sColumnNm>\\\" \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "\n"
    "  locals| sTableNm sIndexNm sColumnNm  |\n"
    "\n"
    "  sColumnNm sIndexNm sTableNm\n"
    "  checkAddIndexColumn not if <NIP+ERROR> exit then\n"
    "\n"
    "  sColumnNm sIndexNm\n"
    "  addIndexColumn ( ) assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* add a partition column                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": add_partcolumn ( \\\"<sColumnNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "\n"
    "  locals| sTableNm sColumnNm  |\n"
    "\n"
    "  sColumnNm sTableNm\n"
    "  checkAddPartitionColumn not if <NIP+ERROR> exit then\n"
    "\n"
    "  sColumnNm sTableNm\n"
    "  addPartitionColumn ( ) assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get list of columns                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": list_columns ( \\\"<sTableNm>\\\" -- <R> )\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  dup checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  dup pushTable assert\n"
    "\n"
    "  // check it is a table\n"
    "  checkIsTable  not if popTable <NIP+ERROR> exit then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(columnDefinition VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  listColumns\n"
    "\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get list of index columns                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": list_indexcolumns ( \\\"<sTableNm\\\" \\\"<sIndexNm>\\\" -- <R> )\n"
    "\n"
    "  locals| sIndexNm sTableNm |\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables       not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert\n"
    "\n"
    "  // check it is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(columnName VARCHAR, columnType VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  sIndexNm listIndexColumns\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes\n"
    "\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "\n"
    "  // assert we are still in tables folder\n"
    "  assertInTables\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get list of partition key columns                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": list_partitioncolumns ( \\\"<sTableNm>\\\" -- <R> )\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  dup checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  dup pushTable assert\n"
    "\n"
    "  // check it is a table\n"
    "  checkIsTable  not if popTable <NIP+ERROR> exit then\n"
    "\n"
    "  args.metadata if\n"
    "  \\\"(columnName VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  listPartitionColumns\n"
    "\n"
    "  // pop table dictionary\n"
    "  popTable\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_column.sen"_Str
  ;

