  // munge of requests_folder.sen
  sDefinition =
    "\""
    "\\\"munged requests_folder.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_folder.sen -- the set of folder related requests                  */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"requests_folder.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a folder                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeFolder allParticipants 1 checkResult ( \\\"<folderNm>\\\" -- true n# true )\n"
    "\n"
    "  tp: removeFolder\n"
    "\n"
    "  :forget\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* change folder to given folder name                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": cf ( \\\"<sFolderNm>\\\" -- R )\n"
    "\n"
    "  locals| sFolderNm |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"..\\\" which will go up one folder\n"
    "\n"
    "  // pop up one folder, but not into tenants\n"
    "  sFolderNm \\\"..\\\" str.equal if\n"
    "    0 pathPick dic.name \\\"tenants\\\" str.equal not if pathDrop then\n"
    "    //\\\"After cf ..\\\" . PATHDUMP\n"
    "    <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"~\\\" will pop folder path till it reaches /tenants\n"
    "\n"
    "  // pop up to tenants\n"
    "  sFolderNm \\\"~\\\" str.equal if\n"
    "    begin 0 pathPick dic.name \\\"tenants\\\" str.equal not while pathDrop repeat\n"
    "    //\\\"After cf ~\\\" . PATHDUMP\n"
    "    <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // test for a \\\"tenants\\\" will clear folder path and set to /tenants\n"
    "\n"
    "  // clear dic path and push tenants\n"
    "  sFolderNm \\\"tenants\\\" str.equal if\n"
    "    //begin 0 pathPick dic.name \\\"<main>\\\" str.equal not while pathDrop repeat\n"
    "    pathDropAll\n"
    "    sFolderNm checkIsWord not if <NIP+ERROR> exit then\n"
    "    execute pathPush\n"
    "    //\\\"After cf tenants\\\" . PATHDUMP\n"
    "   <OK>\n"
    "    exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // otherwise we expect a name of a sub -folder to which we push path to\n"
    "\n"
    "  // push sub-folder\n"
    "  sFolderNm findInCurrent\n"
    "  checkIsDic not if <NIP+ERROR> exit then\n"
    "  execute pathPush\n"
    "  //\\\"After cf <dicNm>\\\" . PATHDUMP\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable folder                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveFolder ( \\\"<folderNm>\\\" -- \\\"<folderNm>\\\" true | \\\"<folderNm>\\\" errorCode false )\n"
    "\n"
    "  dup ( \\\"<folderNm>\\\" \\\"<folderNm>\\\" )\n"
    "\n"
    "  checkIsWord     not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "  checkIsEmpty    not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "  checkNotUsed    not if false exit then ( \\\"<folderNm>\\\" word )\n"
    "\n"
    "  drop ( \\\"<folderNm>\\\" )\n"
    "\n"
    "  true ( \\\"<folderNm>\\\" true )\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a folder                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": remove_folder ( \\\"<folderNm>\\\" -- <R> )\n"
    "\n"
    "  tp: dropDic\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  checkRemoveFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  removeFolder ( ) assert::stack_0\n"
    "\n"
    "  tp: droppedDic\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf\n"
    "\n"
    "  0 locals| iCount |\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(name VARCHAR, type VARCHAR)\\\" metadata!\n"
    "    \\\"\\\"\n"
    "    0 pathPick dic.lastWord dup iterate\n"
    "    //dup str.length if \\\"\\\\n\\\" str.cat then\n"
    "    1 iCount + to iCount\n"
    "    \\\"row: ('\\\" str.cat\n"
    "\n"
    "    object@ word.name str.cat\n"
    "\n"
    "    \\\"', \\\" str.cat\n"
    "\n"
    "    object@ isTable if\n"
    "      \\\"'table'\\\" str.cat\n"
    "      //object@ execute table.space bytes.magnitude str.cat\n"
    "    then\n"
    "\n"
    "    object@ isIndex if\n"
    "      \\\"'index'\\\" str.cat\n"
    "      //object@ execute table.space bytes.magnitude str.cat\n"
    "    then\n"
    "\n"
    "    object@ isFolder if\n"
    "      \\\"'\\\" str.cat\n"
    "      object@ execute dic.kind@ word.name str.cat\n"
    "      \\\"'\\\" str.cat\n"
    "    then\n"
    "\n"
    "    iCount if\n"
    "      \\\")\\\\n\\\" str.cat\n"
    "    then\n"
    "\n"
    "    object@ word.prev object!\n"
    "\n"
    "    next\n"
    "    iCount task::this task.seitf@ seitf.rowsProcessed\n"
    "  else\n"
    "    \\\"\\\"\n"
    "    0 pathPick dic.lastWord dup iterate\n"
    "\n"
    "      dup str.length if \\\"\\\\n\\\" str.cat then\n"
    "\n"
    "      object@ word.name 12 str.pad str.cat\n"
    "      1 iCount + to iCount\n"
    "      \\\"(\\\" str.cat\n"
    "\n"
    "      object@ isTable if\n"
    "        \\\"table \\\" str.cat\n"
    "        //object@ execute table.space bytes.magnitude str.cat\n"
    "      then\n"
    "\n"
    "      object@ isIndex if\n"
    "        \\\"index\\\" str.cat\n"
    "        //object@ execute table.space bytes.magnitude str.cat\n"
    "      then\n"
    "\n"
    "      object@ isFolder if\n"
    "        object@ execute dic.kind@ word.name str.cat\n"
    "      then\n"
    "\n"
    "      object@ word.prev object!\n"
    "\n"
    "    next\n"
    "    iCount if\n"
    "      \\\")\\\" str.cat\n"
    "    then\n"
    "  then\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": ~lf ( )\n"
    "\n"
    "  tp: lfOnAll\n"
    "\n"
    "  // set indirect call to be lf_\n"
    "  << \\\"lf_\\\"\n"
    "\n"
    "  tp: theIndirectCall\n"
    "\n"
    "  >> ( valset )\n"
    "\n"
    "  >>allParticipants> ( bool )\n"
    "\n"
    "  tp: lfOnAllDone\n"
    "\n"
    "  checkResult\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents across the grid                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lfG\n"
    "\n"
    "  ~lf\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf$ ( )\n"
    "\n"
    "  tp: lf\n"
    "\n"
    "  \\\"LISTING FOLDER on NODE \\\" grid.thisNode@ >str str.cat .\n"
    "\n"
    "  \\\"\\\"\n"
    "  0 pathPick dic.lastWord dup iterate\n"
    "\n"
    "  dup str.length if \\\"\\\\n\\\" str.cat then\n"
    "\n"
    "  object@ word.name 12 str.pad str.cat\n"
    "\n"
    "  \\\"(\\\" str.cat\n"
    "\n"
    "  object@ isTable if\n"
    "  \\\"table \\\" str.cat\n"
    "  object@ execute table.space bytes.magnitude str.cat\n"
    "  then\n"
    "\n"
    "  object@ isFolder if\n"
    "  object@ execute dic.kind@ word.name str.cat\n"
    "  then\n"
    "\n"
    "  \\\")\\\" str.cat\n"
    "\n"
    "  object@ word.prev object!\n"
    "\n"
    "  next\n"
    "\n"
    "  .\n"
    "\n"
    "  //drop ( \\\"<tenantNm>\\\" )\n"
    "\n"
    "  true ( true )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* list folder contents                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lf_ (  #folders -- true )\n"
    "\n"
    "  depth 0 != if\n"
    "    \\\"dicPath.set\\\" str.equal\n"
    "    if\n"
    "  tp: settingDicStack\n"
    "    !indirect drop\n"
    "    then\n"
    "  then\n"
    "\n"
    "  lf$\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* print working folder                                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": pwf ( - sPath <SUCCESS> )\n"
    "\n"
    "  // test if we need to produce meta data\n"
    "  args.metadata if\n"
    "    \n"
    "    // set meta data information\n"
    "    \\\"(path VARCHAR)\\\" metadata!\n"
    "\n"
    "    // start of working string\n"
    "    \\\"row: ('/\\\"\n"
    "\n"
    "    // iterate thru each folder in path\n"
    "    pathDepth 0 do\n"
    "      // compute the path subscript\n"
    "      pathDepth 1 - I -\n"
    "      // pick the path, get its name and concat name to working string\n"
    "      pathPick dic.name str.cat\n"
    "      // concat \\\"/\\\" to end of working string\n"
    "      \\\"/\\\" str.cat\n"
    "    loop\n"
    "\n"
    "    // end working string\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "\n"
    "    // set number of rows processed\n"
    "    1 task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  else\n"
    "\n"
    "    // start of working string\n"
    "    \\\"/\\\"\n"
    "\n"
    "    // iterate thru each folder in path and concat to end\n"
    "    pathDepth 0 do\n"
    "      // compute the path subscript\n"
    "      pathDepth 1 - I -\n"
    "      // pick the path, get its name and concat name to working string\n"
    "      pathPick dic.name str.cat\n"
    "      // concat \\\"/\\\" to end of working string\n"
    "      \\\"/\\\" str.cat\n"
    "    loop\n"
    "\n"
    "  then\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create /tenants/boray/catalogs/rapidsse                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": createDefaultFolders localCalls ( )\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  // push tenants folder\n"
    "  \\\"tenants\\\" find execute\n"
    "  pathPush\n"
    "\n"
    "    // create tenant boray (and catalogs sub-folder)\n"
    "    \\\"boray\\\" makeTenant drop drop drop\n"
    "\n"
    "    // push boray folder\n"
    "    \\\"boray\\\" findInCurrent execute\n"
    "    pathPush\n"
    "\n"
    "      // push catalogs folder\n"
    "      \\\"catalogs\\\" findInCurrent execute\n"
    "      pathPush\n"
    "\n"
    "        // create catalog rapidsse (and schemas sub-folder)\n"
    "        \\\"rapidsse\\\" makeCatalog drop drop drop\n"
    "\n"
    "          // push rapidsse folder\n"
    "          \\\"rapidsse\\\" findInCurrent execute\n"
    "          pathPush\n"
    "\n"
    "          // push schemas folder\n"
    "          \\\"schemas\\\" findInCurrent execute\n"
    "          pathPush\n"
    "\n"
    "          // create schema public (and tables sub-folder)\n"
    "          \\\"public\\\" makeSchema drop drop drop\n"
    "\n"
    "          pathDrop\n"
    "      pathDrop\n"
    "    pathDrop\n"
    "  pathDrop\n"
    "\n"
    "  assert::stack_0\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_folder.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of requests_grid.sen
  sDefinition =
    "\""
    "\\\"munged requests_grid.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_grid.sen -- the set of grid related requests                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"requests_grid.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get status of nodes in the grid (run by participant)                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": get_status allParticipants 0 returnResult ( -- str n# true )\n"
    "\n"
    "tp: gettingStatus\n"
    "\n"
    "  args.tracepoint if\n"
    "  \\\"GETTING STATUS on NODE \\\"grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  node.status\n"
    "\n"
    "  <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get status of the nodes                                                    */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": status ( -- <R> )\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(nodeName VARCHAR, instanceName VARCHAR, status VARCHAR)\\\"  metadata!\n"
    "  then\n"
    "\n"
    "  get_status ( str )\n"
    "\n"
    "  not if <NIP+ERROR> else <SUCCESS> then\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_grid.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of requests_index.sen
  sDefinition =
    "\""
    "\\\"munged requests_index.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* requests_index.sen -- the set of index related requests                    */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"requests_index.sen\\\" .verbose\n"
    "\n"
    "timer: idxSelectTimer\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyse an index of a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyzeIdx ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" bDetailed -- <R> )\n"
    "                                                                    // ../tables\n"
    "  tp: analyzeIdx\n"
    "\n"
    "  locals| bDetailed sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables       not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> assertInTables exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "     popIndexes popTable                                            // ../tables\n"
    "     assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // analyse the index\n"
    "  bDetailed not if\n"
    "    args.metadata if\n"
    "      \\\"(nodeName VARCHAR, partition INTEGER, bufferNo INTEGER, bufferLevel INTEGER, entries INTEGER)\\\"\n"
    "        metadata!\n"
    "    then\n"
    "  then\n"
    "\n"
    "  bDetailed sIndexNm analyzeIndex ( )\n"
    "\n"
    "  // set no of rows processed equal to total no of partitions\n"
    "  grid.partitions task::this task.seitf@ seitf.rowsProcessed\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path \n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: analyzedIndex\n"
    "\n"
    "  not if <NIP+ERROR> else <SUCCESS> then\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyse an index of a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": analyze_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "   0 analyzeIdx\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* analyse an index of a table                                                */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": danalyze_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "  1 analyzeIdx\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an index on a table                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": create_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  tp: create_index\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  checkEnoughBuffers not if <NIP+ERROR> exit then\n"
    "  sIndexNm sTableNm checkMakeIndex  not if <NIP+ERROR> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create index\n"
    "\n"
    "  //sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "  //sTableNm get_table\n"
    "  //popTable                                                          // ../tables\n"
    "\n"
    "  sTableNm sIndexNm makeIndex assertInTables\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* drop an index                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": drop_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  tp: dropIndex\n"
    "\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  sIndexNm sTableNm checkRemoveIndex not if <NIP+ERROR> exit then\n"
    "\n"
    "  tp ( \\\"<sIndexNm>\\\" )\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert ( \\\"<sIndexNm>\\\" )               // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert ( \\\"<sIndexNm>\\\" )              // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check it is an index we are dropping\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  sIndexNm \\\"hidden\\\" str.equal if\n"
    "    popIndexes popTable assertInTables EC_NO_SUCH_INDEX <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // remove the index\n"
    "\n"
    "  sIndexNm removeIndex ( ) assert::stack_0\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: droppedIndex\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* dump index                                                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": dump_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // dump index\n"
    "\n"
    "  sIndexNm find execute\n"
    "  index.dump\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: dumpedIndex\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* end of create index sequence                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": end_create_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                    // ../tables/tableNm/indexes\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  tp: end_create_index\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "  checkInIndexes not if <NIP+ERROR> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // create column vector and populate index\n"
    "\n"
    "  // create the column vector of the index\n"
    "  sIndexNm columnVecIndex\n"
    "\n"
    "  // now populate the index\n"
    "  sIndexNm find execute ( ^index )\n"
    "  index.populate                                    // ../tables/tableNm/indexes\n"
    "\n"
    "  // pop indexes folder temporarily\n"
    "  popIndexes                                                // ../tables/tableNm\n"
    "\n"
    "  // return the table reference\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  // push back the indexes folder\n"
    "  pushIndexes assert                                // ../tables/tableNm/indexes\n"
    "\n"
    "  assertInIndexes\n"
    "\n"
    "  assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* fetch rows using an index                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": fetch_rows_index ( \\\"<sWhere>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "\\\"fetch_rows_index\\\" .\n"
    "\n"
    "  assert::stack_2\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "\n"
    "  0 0 0 locals| pPlanner pAccessPath pTable sTableNm sWhere |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  sTableNm find execute to pTable\n"
    "\n"
    "/*\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "  popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "*/\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // lower bound select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "  \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // create access path and put into seitf\n"
    "  //accessPath::new to pAccessPath\n"
    "  //pAccessPath task::this task.seitf@ seitf.accessPath!\n"
    "\n"
    "  ( cdt_0 ) planner::new to pPlanner\n"
    "  ( cdt_1 ) pTable pPlanner Planner.table!\n"
    "\n"
    "  ( cdt_2 ) pPlanner Planner.genPaths           \\\"genPaths\\\" .\n"
    "  ( cdt_3 ) pPlanner Planner.scorePaths         \\\"scorePaths\\\" .\n"
    "  //( cdt_4 ) pPlanner Planner.showPaths\n"
    "\n"
    "  ( cdt_5 ) sWhere pPlanner Planner.parseWhere  \\\"parseWheres\\\" .\n"
    "  //( cdt_4 ) pPlanner Planner.showPaths\n"
    "  ( cdt_7 ) pPlanner Planner.matchPaths         \\\"matchPaths\\\" .\n"
    "  //( cdt_8 ) pPlanner Planner.showPaths\n"
    "  ( cdt_9 ) pPlanner Planner.choosePath         \\\"choosePaths\\\" .\n"
    "\n"
    "  pPlanner Planner.fetchTechnique@\n"
    "\n"
    "  // execute a lower bound select using index\n"
    "  case\n"
    "    AT_EXACT of\n"
    "      \\\"case equal\\\" .\n"
    "      pPlanner Planner.key@\n"
    "      \\\"0\\\"  //lower\n"
    "      \\\"0\\\"  //upper\n"
    "      \\\"keySelectIdxTask\\\"\n"
    "      pPlanner Planner.indexNm@\n"
    "      selectIndex\n"
    "    endof\n"
    "\n"
    "    AT_LOWER of\n"
    "      \\\"case lower\\\" .\n"
    "      \\\"0\\\" //key\n"
    "      pPlanner Planner.lowKey@\n"
    "      \\\"0\\\" //upper\n"
    "      \\\"lowerSelectIdxTask\\\"\n"
    "      pPlanner Planner.indexNm@\n"
    "      selectIndex\n"
    "    endof\n"
    "\n"
    "    AT_UPPER of\n"
    "      \\\"case upper\\\" .\n"
    "      \\\"0\\\" //key\n"
    "      \\\"0\\\" //lower\n"
    "      pPlanner Planner.highKey@\n"
    "      \\\"upperSelectIdxTask\\\"\n"
    "      pPlanner Planner.indexNm@\n"
    "      selectIndex\n"
    "    endof\n"
    "\n"
    "    AT_RANGE of\n"
    "      \\\"case range\\\" .\n"
    "      \\\"0\\\" //key\n"
    "      pPlanner Planner.lowKey@\n"
    "      pPlanner Planner.highKey@\n"
    "      \\\"rangeSelectIdxTask\\\"\n"
    "      pPlanner Planner.indexNm@\n"
    "      selectIndex\n"
    "    endof\n"
    "\n"
    "    AT_SCAN of\n"
    "      \\\"case scan\\\" .\n"
    "      \\\"0\\\" //key\n"
    "      \\\"0\\\" //lower\n"
    "      \\\"0\\\" //upper\n"
    "      \\\"scanSelectIdxTask\\\"\n"
    "      \\\"hidden\\\"\n"
    "      selectIndex\n"
    "    endof\n"
    "  endcase\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  pPlanner planner.delete\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "  idxSelectTimer timer.update\n"
    "  \\\"select time \\\" .put\n"
    "  idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get an index                                                               */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": get_index ( \\\"<indexNm>\\\" -- <R> )\n"
    "\n"
    "  getIndex not if <NIP+ERROR> exit then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get list of indexes                                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": list_indexes ( \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // list indexes\n"
    "  listIndexesContents\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* exact key select of table given an index                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": key_select_index ( \\\"<xKey>\\\" \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  assert::stack_3\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "  CN_STRVAL assert::class_2\n"
    "\n"
    "  locals| sTableNm sIndexNm xKey |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // exact key select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "    \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // execute a exact key select using index\n"
    "  xKey \\\"0\\\" \\\"0\\\" \\\"keySelectIdxTask\\\" sIndexNm selectIndex ( lower index )\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  // pop named table folder off path\n"
    "  // i.e. task.dicStack will now be back to ../tables\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "    idxSelectTimer timer.update\n"
    "    \\\"select time \\\" .put\n"
    "    idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* lower bound select of table given an index                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": lower_select_index ( \\\"<sLower>\\\" \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "\\\"lower_select_index\\\" .\n"
    "\n"
    "  assert::stack_3\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "  CN_STRVAL assert::class_2\n"
    "\n"
    "  locals| sTableNm sIndexNm sLower |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "    not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // lower bound select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "   \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // execute a lower bound select using index\n"
    "  \\\"0\\\" sLower \\\"0\\\" \\\"lowerSelectIdxTask\\\" sIndexNm selectIndex ( lower index )\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "    idxSelectTimer timer.update\n"
    "    \\\"select time \\\" .put\n"
    "    idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* range select of table given an index                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": range_select_index ( \\\"<sUpper>\\\" \\\"<sLower>\\\" \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  tp: range_select_index\n"
    "\n"
    "  assert::stack_4\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "  CN_STRVAL assert::class_2\n"
    "  CN_STRVAL assert::class_3\n"
    "\n"
    "  locals| sTableNm sIndexNm sLower sUpper |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // range select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "    \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // execute a range select on idx\n"
    "  \\\"0\\\" sLower sUpper \\\"rangeSelectIdxTask\\\" sIndexNm selectIndex ( upper lower index )\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "    idxSelectTimer timer.update\n"
    "    \\\"select time \\\" .put\n"
    "    idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* scan select of table given an index                                        */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scan_select_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "  // ../tables\n"
    "  tp: scan_select_index\n"
    "\n"
    "  assert::stack_2\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "  popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // range select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "  \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // execute a range select on idx\n"
    "  \\\"0\\\" \\\"0\\\" \\\"0\\\" \\\"scanSelectIdxTask\\\" sIndexNm selectIndex ( upper lower index )\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "  idxSelectTimer timer.update\n"
    "  \\\"select time \\\" .put\n"
    "  idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* return an index                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": return_index ( \\\"<indexNm>\\\" -- <R> )\n"
    "\n"
    "  returnIndex not if <NIP+ERROR> exit then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* set unique property of an index                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": index_setUnique ( true/false \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                   // ../tables/sTableNm/indexes\n"
    "  assert::stack_3\n"
    "\n"
    "  locals| sTableNm sIndexNm bIsUnique |\n"
    "\n"
    "  tp: index_setUnique\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "  checkInIndexes not if <NIP+ERROR> exit then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // uniqueness\n"
    "  bIsUnique sIndexNm setIndexIsUnique ( ) assert::stack_0\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* get size of index                                                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": size_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabWrite\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check there is an index of the name\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // get index size\n"
    "  sIndexNm sizeIndex ( \\\"<size>\\\" )\n"
    "\n"
    "  args.metadata if\n"
    "    \\\"(size VARCHAR)\\\" metadata!\n"
    "    \\\"row: ('\\\" swap str.cat\n"
    "    \\\"')\\\\n\\\" str.cat\n"
    "    1 task::this task.seitf@ seitf.rowsProcessed\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  <SUCCESS>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* truncate index                                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": truncate_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table folder\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check there is an index of the name\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // truncate index\n"
    "\n"
    "  // find the index\n"
    "  sIndexNm find execute\n"
    "\n"
    "  // truncate the index\n"
    "  index.truncate\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* upper bound select of table given an index                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": upper_select_index ( \\\"<sUpper>\\\" \\\"<sIndexNm>\\\" \\\"<sTableNm>\\\" -- <R> )\n"
    "                                                                    // ../tables\n"
    "  assert::stack_3\n"
    "  CN_STRVAL assert::class_0\n"
    "  CN_STRVAL assert::class_1\n"
    "  CN_STRVAL assert::class_2\n"
    "\n"
    "  locals| sTableNm sIndexNm sUpper |\n"
    "\n"
    "  idxSelectTimer timer.start\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  //\n"
    "  // task will have an seitf and a dicStack path, but seitf has no table\n"
    "  //\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // path should end in a tables folder\n"
    "  // i.e. task.dicStack should be ../tables\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // check \\\"<sTableNm>\\\" is a table folder within ../tables\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push named table folder onto path\n"
    "  // i.e. task.dicStack will be ../tables/<sTableNm>\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // check \\\"<sTableNm\\\"> is a table in ../tables/<sTableNm>\n"
    "  sTableNm checkIsTable not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  // check sIndexNm is an index\n"
    "  sIndexNm checkIsIndex\n"
    "  not if\n"
    "    popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // pop indexes folder\n"
    "  popIndexes                                               // ../tables/sTableNm\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // upper select\n"
    "\n"
    "  // set the metadata string\n"
    "  args.metadata if\n"
    "    \\\"(partition INTEGER, data VARCHAR)\\\" metadata!\n"
    "  then\n"
    "\n"
    "  // get and inc table reference and put into task.seitf.currentTable\n"
    "  getTableRef not if <NIP+ERROR> exit then\n"
    "  task::this task.seitf@ seitf.table@ assert\n"
    "\n"
    "  // execute a lower bound select using index\n"
    "  \\\"0\\\" \\\"0\\\" sUpper \\\"upperSelectIdxTask\\\" sIndexNm selectIndex ( upper index )\n"
    "\n"
    "  // dec and return table reference and clear task.seitf.currentTable\n"
    "  returnTableRef not if <NIP+ERROR> exit then\n"
    "\n"
    "  // assert no seitf.table\n"
    "  task::this task.seitf@ seitf.table@ not assert\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popTable assertInTables                                           // ../tables\n"
    "\n"
    "  args.metadata not if\n"
    "    idxSelectTimer timer.update\n"
    "    \\\"select time \\\" .put\n"
    "    idxSelectTimer timer.millisecs .put \\\"ms\\\" .put .\\\\n\n"
    "  then\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* visualize index                                                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": visualize_index ( \\\"<sIndexNm>\\\" \\\"<sTableNm\\\" -- <R> )\n"
    "  // ../tables\n"
    "  locals| sTableNm sIndexNm |\n"
    "\n"
    "  ddlLock::grabRead\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // checks\n"
    "\n"
    "  // should be in the tables folder\n"
    "  checkInTables not if <NIP+ERROR> exit then\n"
    "\n"
    "  // there should be a table folder\n"
    "  sTableNm checkIsTableFolder not if <NIP+ERROR> exit then\n"
    "\n"
    "  // push table dictionary\n"
    "  sTableNm pushTable assert                                // ../tables/sTableNm\n"
    "\n"
    "  // push indexes folder\n"
    "  pushIndexes assert                               // ../tables/sTableNm/indexes\n"
    "\n"
    "  sIndexNm checkIsIndex not if\n"
    "  popIndexes popTable assertInTables <NIP+ERROR> exit\n"
    "  then\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // visualize index\n"
    "\n"
    "  sIndexNm find execute\n"
    "  index.visualize\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // restore path\n"
    "\n"
    "  popIndexes popTable assertInTables                                // ../tables\n"
    "\n"
    "  tp: dumpedIndex\n"
    "\n"
    "  <OK>\n"
    " ;\n"
    "\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT requests_index.sen"_Str
  ;

