  // munge of scanOp.sen
  sDefinition =
    "\""
    "\\\"munged scanOp.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* scanOp.sen -- table scan select operator                                   */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"scanOp.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* frame-level variables for scan                                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "common/ scan rbCrs /\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* scan partition of a table                                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanPartition subDic scan ( profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile |\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set path (hardcoded for the moment)\n"
    "\n"
    "  //\\\"tables\\\" \\\"tpchSchema\\\" \\\"schemas\\\" \\\"rapidsse\\\" \\\"catalogs\\\" \\\"boray\\\" \\\"tenants\\\" 7 dicPath.set\n"
    "  \\\"tenants\\\" 1 dicPath.set\n"
    "\n"
    "  // [0] push thePlan's dictionary onto path stack\n"
    "  thePlan plan.dic pathPush\n"
    "\n"
    "  // [1] find and push opFrame (along with its dictionary onto path stack)\n"
    "  profile thePlan plan.opFrame? opFrame.push // [1]\n"
    "  //pathDump\n"
    "\n"
    "  $$tableNm   locals| tableNm   |\n"
    "  $$schemaNm  locals| schemaNm  |\n"
    "  $$catalogNm locals| catalogNm |\n"
    "\n"
    "  // drop the dictionary path\n"
    "  pathDrop\n"
    "\n"
    "  // now create the dictionary path again with the catalog and schemaNm\n"
    "  \\\"catalogs\\\" \\\"boray\\\" \\\"tenants\\\" 3 dicPath.set\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  catalogNm find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  \\\"schemas\\\" find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  schemaNm find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm folder on the dictionary path\n"
    "  \\\"tables\\\" find execute\n"
    "  pathPush\n"
    "\n"
    "  // push tableNm on the dictionary path\n"
    "  tableNm find execute\n"
    "  pathPush\n"
    "\n"
    "  //pathDump\n"
    "\n"
    "  // [0] push thePlan's dictionary onto path stack\n"
    "  thePlan plan.dic pathPush\n"
    "\n"
    "  // [1] find and push opFrame (along with its dictionary onto path stack)\n"
    "  profile thePlan plan.opFrame? opFrame.push // [1]\n"
    "\n"
    "  // [2] create a new rowCursor and record in opFrame.rbCrs\n"
    "  rbCursor::new toCommon rbCrs\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // set up table in rowCursor\n"
    "  $$tableNm find execute rbCrs rbCursor.table!\n"
    "\n"
    "  // begin scan of partition\n"
    "  $$partition grid::toSlot rbCrs rbCursor.begin\n"
    "\n"
    "  // get first rowBuffer of partition\n"
    "  rbCrs rbCursor.first\n"
    "\n"
    "  // pipe all rb's of partition\n"
    "  begin while\n"
    "      \n"
    "    // << rb true profile plan profile >> -->> nextOp\n"
    "    << rbCrs rbCursor.get true $$nextProfile thePlan plan.id@ $$nextOp >>jobQueue\n"
    "\n"
    "    // next rowBuffer in partition\n"
    "    rbCrs rbCursor.next\n"
    "\n"
    "  repeat\n"
    "\n"
    "  // end cursored iteration\n"
    "  rbCrs rbCursor.end\n"
    "\n"
    "  // pipe EOD to writeOp\n"
    "  // << false plan >> -->> nextOp\n"
    "  << false $$nextProfile thePlan plan.Id@ $$nextOp >>jobQueue\n"
    "\n"
    "  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n"
    "  // [2] delete cursor\n"
    "  rbCrs rbCursor.delete\n"
    "  0 toCommon rbCrs\n"
    "\n"
    "  // [1] discard opFrame (and dictionary)\n"
    "  opFrame.drop\n"
    "\n"
    "  // [0] discard thePlan's dictionary from path stack\n"
    "  pathDrop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* table scan operator loop                                                   */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": scanOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    //grid.thisNode@ \\\"SCANOP: NODE %V\\\" str.format .\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( profile planId nValues )\n"
    "    drop ( profile planId )\n"
    "\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( profile plan true )\n"
    "    assert ( profile plan )\n"
    "\n"
    "    // scan the table partition and pipe to write\n"
    "    scanPartition ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT scanOp.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of schema.sen
  sDefinition =
    "\""
    "\\\"munged schema.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* schema.sen -- schema related words                                         */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"schema.sen\\\" .verbose\n"
    "\n"
    ": schema ;\n"
    "\n"
    "//: makeSchemas pathPush \\\"schemas\\\" :dic ' folder swap execute dic.kind! pathDrop ;\n"
    "\n"
    "\n"
    ": :schema\n"
    "    :dic\n"
    "         //dup ' schema swap word.kind!\n"
    "         dup ' schema swap execute dic.kind!\n"
    " ;\n"
    "\n"
    ": withinSchemas\n"
    "    0 pathPick dic.name \\\"schemas\\\" str.equal\n"
    " ;\n"
    "\n"
    ": checkInSchemas\n"
    "    withinSchemas if true exit then\n"
    "    EC_NOT_IN_SCHEMAS false\n"
    " ;\n"
    "\n"
    ": checkIsSchema ( word )\n"
    "\n"
    "    dup word.kind@ ' folder eql not if EC_NOT_A_FOLDER false exit then\n"
    "    dup execute dic.kind@ ' schema eql if true exit then\n"
    "    EC_NOT_A_SCHEMA false\n"
    " ;\n"
    "\n"
    ": checkIsNotSchema ( word )\n"
    "  dup findInCurrent not if true exit then\n"
    "  EC_SCHEMA_EXISTS false\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a makeable schema folder                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkMakeSchema ( \\\"<schemaNm>\\\" -- \\\"<schemaNm>\\\" true | \\\"<schemaNm>\\\" errorCode false )\n"
    "\n"
    "  checkInSchemas   not if false exit then\n"
    "  checkIsNotSchema not if false exit then\n"
    "\n"
    "  true\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schemas folder under given named catalog                            */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeSchemas ( \\\"<catalogNm>\\\" -- )\n"
    "\n"
    "  args.tracepoint if\n"
    "    dup \\\"MAKING SCHEMAS FOR CATALOG \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  find execute ( dic )\n"
    "  \\\"schemas\\\"    ( dic \\\"schemas\\\" )\n"
    "  swap         ( \\\"schemas\\\" dic )\n"
    "  :folder      ( )\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* check if word is a removable schema folder                                 */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": checkRemoveSchema ( \\\"<schemaNm>\\\" -- \\\"<schemaNm>\\\" true | \\\"<schemaNm>\\\" errorCode false )\n"
    "\n"
    "  dup ( \\\"<schemaNm>\\\" \\\"<schemaNm>\\\" )\n"
    "\n"
    "  checkInSchemas not if false exit then ( \\\"<schemaNm>\\\" word )\n"
    "  checkIsWord    not if false exit then ( \\\"<schemaNm>\\\" word )\n"
    "  checkIsSchema  not if false exit then ( \\\"<schemaNm>\\\" word )\n"
    "  checkIsEmpty   not if false exit then ( \\\"<schemaNm>\\\" word )\n"
    "  checkNotUsed   not if false exit then ( \\\"<schemaNm>\\\" word )\n"
    "\n"
    "  drop ( \\\"<schemaNm>\\\" )\n"
    "\n"
    "  true ( \\\"<schemaNm>\\\" true )\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* make a schema folder (run by participant)                                  */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": makeSchema allParticipants 1 checkResult ( \\\"<schemaNm>\\\" -- true n# true )\n"
    "\n"
    "tp: makingSchema\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \\\"MAKING SCHEMA \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  dup ( \\\"<schemaNm>\\\" )\n"
    "\n"
    "  :schema ( \\\"<schemaNm>\\\" ^schema )\n"
    "\n"
    "  drop ( \\\"<schemaNm>\\\" )\n"
    "\n"
    "  makeTables ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* remove a schema folder                                                     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": removeSchema allParticipants 1 checkResult ( \\\"<schemaNm>\\\" -- true n# true )\n"
    "\n"
    "tp: removeSchema\n"
    "\n"
    "  args.tracepoint if\n"
    "  dup \\\"REMOVING TENANT \\\" swap str.cat \\\" on NODE \\\" str.cat grid.thisNode@ >str str.cat .\n"
    "  then\n"
    "\n"
    "  :forget ( )\n"
    "\n"
    "  true <SUCCESS_RESULT>\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT schema.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of seitfCursor.sen
  sDefinition =
    "\""
    "\\\"munged seitfCursor.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* seitfCursor.sen -- SEitf Cursor                                            */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"seitfCursor.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a seitfCursor using name from input stream                          */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": seitfCursor:\n"
    "\n"
    "  create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_seitfCursor allot\n"
    "  word.this >body object.magic!\n"
    "  CN_SEITFCURSOR word.this >body object.class!\n"
    "  word.this >body seitfCursor.init\n"
    "  true word.this >body object.wordbody!\n"
    "  does>\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create a seitfCursor using name on the stack             (leaves on stack) */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": :seitfCursor\n"
    "\n"
    "  >create\n"
    "  WT_OBJECT word.this word.type!\n"
    "  sizeof_seitfCursor allot\n"
    "  word.this >body object.magic!\n"
    "  CN_SEITFCURSOR word.this >body object.class!\n"
    "  word.this >body seitfCursor.init\n"
    "  true word.this >body object.wordbody!\n"
    "  word.this\n"
    "  does>\n"
    " ;\n"
    "\n"
    "////////////////////////////////////////////////////////////////////////////////\n"
    "\n"
    ": ::seitfCursor ( create a temporary seitfCursor )\n"
    "\n"
    "  \\\"__seitfCursor__\\\" find dup\n"
    "  not if\n"
    "    drop\n"
    "    \\\"__seitfCursor__\\\" :seitfCursor\n"
    "  then\n"
    "  execute\n"
    " ;\n"
    "\n"
    ": ~seitfCursor ( forget temporary seitfCursor )\n"
    "\n"
    "  \\\"__seitfCursor__\\\" find word.forget\n"
    " ;\n"
    "\n"
    ": listSeitf ( list all seitfs )\n"
    "\n"
    "  ::seitfCursor >r // r0 ^seitfCursor\n"
    "\n"
    "  r0 seitfCursor.begin\n"
    "  r0 seitfCursor.first\n"
    "  begin\n"
    "    while\n"
    "    r0 seitfCursor.get\n"
    "    seitf.dump\n"
    "    r0 seitfCursor.next\n"
    "  repeat\n"
    "\n"
    "  rdrop\n"
    "\n"
    "  ~seitfCursor\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT seitfCursor.sen"_Str
  ;

