  // munge of serverModel.sen
  sDefinition =
    "\""
    "\\\"munged serverModel.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* serverModel.sen -- server actor model                                      */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"serverModel.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* compute the number of server processing threads to be created              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": nServerThreads ( memorySize -- nThreads )\n"
    "\n"
    "  // the number of query threads is computed based on the\n"
    "  // size of the region\n"
    "\n"
    "  // there will be 1 query thread per GB\n"
    "  // the number of threads will be limited to 80% of the number of cores\n"
    "\n"
    "  C_1GB / locals| nThreads |\n"
    "\n"
    "//1 exit // temp\n"
    "\n"
    "  nThreads 0 <= if\n"
    "    1\n"
    "  else\n"
    "    nThreads CORE_COUNT 8 * 10 / > if\n"
    "      CORE_COUNT 8 * 10 / to nThreads\n"
    "    then\n"
    "  then\n"
    "\n"
    "  nThreads\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* define the N_SERVER_THREADS constant                                       */\n"
    "/*----------------------------------------------------------------------------*/\n"
    "args.regionSize nServerThreads constant N_SERVER_THREADS\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create and spawn the server processing threads                             */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": >serverNm ( i -- s ) \\\"generalThread\\\"    swap >str str.cat ;\n"
    ": :serverThread   ( i -- w ) >serverNm    :thread    ;\n"
    "\n"
    ": startSeverThreads\n"
    "\n"
    "  0 locals| pServerThread |\n"
    "\n"
    "  args.progress if\n"
    "    N_SERVER_THREADS \\\"General threads: %v\\\" str.format .\n"
    "  then\n"
    "\n"
    "  args.verbose if\n"
    "    \\\"N_SERVER_THREADS \\\" .put N_SERVER_THREADS .put .\\\\n\n"
    "  then\n"
    "\n"
    "  N_SERVER_THREADS 0 do\n"
    "\n"
    "    // create a thread called queryThreadI\n"
    "    I :serverThread execute to pServerThread\n"
    "\n"
    "    // set the threads name\n"
    "    I >serverNm pServerThread thread.name!\n"
    "\n"
    "    // set actor model in the thread\n"
    "    AC_SERVER pServerThread thread.actorModel!\n"
    "\n"
    "    // give it a private taskset\n"
    "    taskset::new pServerThread thread.taskset!\n"
    "\n"
    "    // spawn os thread\n"
    "    pServerThread thread.spawn_server\n"
    "\n"
    "  loop\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* create an actor using given arguments and append to general task queue     */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": spawnServerActor ( ... nArgs sSeedWord pParentTask sTaskNm eTaskKind -- )\n"
    "\n"
    "  nullptr locals| pTask eTaskKind sTaskNm pParent sSeedWord nArgs |\n"
    "\n"
    "  // create a new task\n"
    "  nArgs sSeedWord pParent AC_SERVER sTaskNm eTaskKind task::new to pTask\n"
    "\n"
    "  // set task name\n"
    "  //sTaskNm pTask task.name!\n"
    "\n"
    "  // set actor model in task\n"
    "  //AC_SERVER pTask task.actorModel!\n"
    "\n"
    "  // append task onto server task queue\n"
    "  pTask scheduler::enqueueServerTask\n"
    "\n"
    "  pTask  // return the task\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT serverModel.sen"_Str
  ;

  vCompileConstant(sDefinition);

  // munge of sinkOp.sen
  sDefinition =
    "\""
    "\\\"munged sinkOp.sen\\\" .verbose \n"
    "/*============================================================================*/\n"
    "/* sinkOp.sen -- sink operator                                                */\n"
    "/*============================================================================*/\n"
    "\n"
    "\\\"sinkOp.sen\\\" .verbose\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sink the plan                                                              */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sinkPlan ( profile plan -- )\n"
    "\n"
    "  // record the plan and profile\n"
    "  locals| thePlan profile |\n"
    "\n"
    "  thePlan planList::removePlan\n"
    "\n"
    "  thePlan plan.delete\n"
    "\n"
    "  //\\\"removed & deleted plan\\\" .\n"
    "  //planList::show\n"
    " ;\n"
    "\n"
    "/*----------------------------------------------------------------------------*/\n"
    "/* sink operator loop                                                         */\n"
    "/*----------------------------------------------------------------------------*/\n"
    ": sinkOp operator ( -- NEVER )\n"
    "\n"
    "  begin\n"
    "\n"
    "    depth 0 != if \\\"stack of task has grown\\\" . debug::trap then\n"
    "\n"
    "    // wait for next job\n"
    "    jobQueue> ( valset )\n"
    "\n"
    "    // unpack it\n"
    "    valset> ( profile planId nValues )\n"
    "    drop ( profile planId )\n"
    "\n"
    "    // find plan using planId\n"
    "    planList::findPlan ( profile plan true )\n"
    "    assert ( profile plan )\n"
    "\n"
    "    // sink the plan\n"
    "    sinkPlan ( )\n"
    "\n"
    "  again\n"
    " ;\n"
    "\n"
    "/*============================================================================*/\n"
    "/* end                                                                        */\n"
    "/*============================================================================*/\n"
    "\""
  " CONSTANT sinkOp.sen"_Str
  ;

